	for x in range(a,b+1):
		for y in range(max(b, c-x), c+1):
			if x+y > c:
				if int((x**2 + y**2 )**0.5) in range(c,d+1):
					if isTriangle(x,y,int((x**2 + y**2 )**0.5)):
						return [x,y,int((x**2 + y**2 )**0.5)]
				for z in range(c, d+1):
					if isTriangle(x,y,z):
						return [x,y,z]


