class Prime():
    def __init__(self, n):
        self.M = m = int(math.sqrt(n)) + 10
        self.A = a = [True] * m
        a[0] = a[1] = False
        self.T = t = [2]
        for j in range(4, m, 2):
            a[j] = False
        for i in range(3, m, 2):
            if not a[i]:
                continue
            t.append(i)
            for j in range(i*i,m,i):
                a[j] = False
        self.ds_memo = {}
        self.ds_memo[1] = set([1])

    def is_prime(self, n):
        return self.A[n]


def main():
    t = I()

    pr = Prime(10**10)
    rr = []
    for _ in range(t):
        n = I()

        ii = pp = None
        for i in range(1, 10**3):
            t = i * (n-1)
            for p in pr.T:
                if p > t and not pr.is_prime(p-t):
                    pp = p - t
                    ii = i
                    break
            if pp:
                break

        a = [[ii] * n for _ in range(n)]
        for i in range(n):
            a[i][i] = pp

        rr.append(JAA(a, "\n", " "))

    return JA(rr, "\n")


