import sys


def solve(s, k):
    l = len(s)
    for i in range(l-1, -1, -1):
        prev = s[max(i-2, 0):i]
        z = s[i] + 1
        while z in prev:
            z += 1
        if z >= k:
            continue
        # Gotcha!
        ret = s[:i] + [z]
        while len(ret) < l:
            prev = ret[max(len(ret)-2, 0):len(ret)]
            z = 0
            while z in prev:
                z += 1
            ret.append(z)
        return ret
    return None


