from collections import defaultdict, deque
from itertools import permutations


class Graph:
    def __init__(self):
        self.E = {}
        self.V = defaultdict(list)

    def put(self, v1, v2):
        if v1 not in self.E:
            self.E[v1] = 1
        if v2 not in self.E:
            self.E[v2] = 1
        self.V[v1].append(v2)
        self.V[v2].append(v1)

    def _adj(self, v1):
        return self.V[v1]

    def bfs(self, v):
        visited = set([v])
        path = [v]
        q = deque([v])
        while q:
            v1 = q.pop()
            for v2 in self._adj(v1):
                if v2 not in visited:
                    visited.add(v2)
                    path.append(v2)
                    q.appendleft(v2)

        return path


