def answer(n,A):
    dp=[1]*32
    dp[0]=dp[1]=0
    for i in range(2,32):
        if dp[i]==1:
            p=2*i
            while p<=31:
                if dp[p]==1:
                    dp[p]=0
                p+=i
    count=1
    res=[0]*n
    for i in range(2,32):
        if dp[i]==1:
            flag=0
            for j in range(n):
                if res[j]==0 and A[j]%i==0:
                    flag=1
                    res[j]=count
            if flag==1:
                count+=1
    return count,res

