import math

def gcd(x, y):
	while(y):
		x, y = y, x % y
	return x

def list_gcd(list):
	curr_gcd = gcd(list[0], list[1])
	for i in range(1, len(list)):
		curr_gcd = gcd(curr_gcd, list[i])
	return curr_gcd

