def checkBeauty (digi):
	total = 0
	for i in range(0,len(digi)):
		total += int(digi[i])
	return total % 3

def modThree (digi):
	one = []
	two = []
	for i in range(0,len(digi)):
		if int(digi[i]) % 3 == 1:
			one.insert(0,i)
		elif int(digi[i]) % 3 == 2:
			two.insert(0,i)
	modResult = []
	modResult.append(one)
	modResult.append(two)
	return modResult

def checkHead (digi):
	if len(digi) == 0: return -1
	while len(digi) > 1:
		if int(digi[0]) == 0:
			digi.pop(0)
		else: break
	return "".join(digi)

