    E = {}
    UF = UnionFind(2 * N)
    for _ in range(M):
        a, b = map(int, input().split())
        ca, cb = C[a], C[b]
        if ca == cb:
            UF.unite(a, b + N)
            UF.unite(a + N, b)
        else:
            if ca > cb:
                ca, cb = cb, ca
            c_ab = ca * (K+1) + cb
            if c_ab in E:
                E[c_ab].append((a, b))
            else:
                E[c_ab] = [(a, b)]

    ok_color_num = 0
    ok_color = [0] * (K+1)
    root_c = [set() for _ in range(K+1)]
    for c in range(1, K+1):
        ok = 1
        for v in V_color[c]:
            r1 = UF.find_root(v)
            r2 = UF.find_root(v+N)
            if r1 == r2:
                ok = 0
                break
            else:
                root_c[c].add(min(r1, r2))
        if ok:
            ok_color_num += 1
            ok_color[c] = 1
        else:
