                        # obviously n=4
                        query('?', "OOCC")
                        if (minID == n):
                            fill(0, 'O')
                            fill(1, 'O')
                            fill(2, 'H')
                            fill(3, 'H')

                    if (s[n - 1] == 'L'):
                        t = s[0:n - 1] + 'C'
                        if (t[n - 2] == 'L'): t = t[0:n - 2] + 'C' + t[n - 1:]
                        query('?', t)
                        if (s[n - 1] == 'L'):
                            fill(n - 1, 'H')
                            if (s[n - 2] == 'L'): fill(n - 2, 'H')
        else:
            maxID = minID
            while (maxID < n - 1 and s[maxID + 1] != 'L'): maxID += 1
            for i in range(minID - 1, -1, -1):
                query('?', s[i + 1:i + 2] + s[minID:maxID + 1])
                if (minID != i):
                    for x in range(i + 1): fill(x, 'O')
                    break

            nextFilled = None
            i = maxID + 1
            while i < n:
                if (s[i] != 'L'):
                    i += 1
                    continue
                nextFilled = i
                while (nextFilled < n and s[nextFilled] == 'L'): nextFilled += 1
                query('?', s[0:i] + s[i - 1])
                if (s[i] == 'L'):
                    if (s[i - 1] != 'O'):
                        fill(i, 'O')
                    else:
                        if (nextFilled == n):
                            query('?', s[0:i] + 'C')
                            if (s[i] == 'L'): fill(i, 'H')
                            for x in range(i + 1, nextFilled): fill(x, s[i])
                        else:
                            for x in range(i, nextFilled): fill(x, s[nextFilled])
                        i = nextFilled - 1
                i += 1
        query('!', s)

