    # print node,sons,g[node]
    for i in range(ls):
        for j in range(k+1):
            d2 = max(k-1-j,0)
            maxd = j+1
            if d2+1<maxd and ls>1:
                d2 = j
            tmp = dp[sons[i]][j]
            for s in range(ls):
                if s==i:
                    continue
                tmp += dp[sons[s]][d2]
            dp[node][maxd] = max(dp[node][maxd],tmp)

    for i in range(k)[::-1]:
        dp[node][i] = max(dp[node][i],dp[node][i+1])



