from collections import Counter

dp = Counter(p)
def eqp(d):
    need = 0

    p = dp

    for key in p:

        if key not in d:
            need += p[key]
            continue

        if d[key] > p[key]:
            return False

        if d[key] < p[key]:
            need += p[key] - d[key]
            continue

    if "?" in d:
        if need != d["?"]:
            return False
        else:
            return True

    else:
        if need == 0:
            return True
        else:
            return False


