    if a == b:
        if a in d:
            ans.append('Yes')
        else:
            ans.append('No')
        continue
    if a > b: a, b = b, a
    x = d.get(a*a//b,-1)
    if x == -1:
        ans.append('No')
        continue
    if a % (x*x):
        ans.append('No')
        continue

    y = a //(x*x)

    if x * x * y == a and x * y * y == b: ans.append('Yes')
    else: ans.append('No')
print('\n'.join(ans))

def isprime(a):
    if(a==1 or a==0 or a==2 ):
        return 0
    x=2
    while x*x<=a:
        if a%x==0:
            return 0
        x+=1
    return 1

