from math import radians, cos, sin, atan2

def rotate(point, alpha):
    x = point[0]
    y = point[1]
    return (x * cos(alpha) - y * sin(alpha), x * sin(alpha) + y * cos(alpha))

def crs(a, b):
    return a[0] * b[1] - a[1] * b[0]

def m(end, start):
    return (end[0] - start[0], end[1] - start[1])

def area(poly):
    ret = 0
    n = len(poly)

    for i in range(n):
        j = (i + 1) % n
        ret += crs(poly[i], poly[j])

    return abs(ret) / 2.0

def intersect(a, b, c, d):
    r = crs(m(c, d), m(a, d)) * crs(m(c, d), m(b, d)) <= 0
    r &= crs(m(b, a), m(c, a)) * crs(m(b, a), m(d, a)) <= 0
    if not r:
        return None

    x1 = a[0]
    y1 = a[1]

    x2 = c[0]
    y2 = c[1]

    dx1 = b[0] - a[0]
    dx2 = d[0] - c[0]

    dy1 = b[1] - a[1]
    dy2 = d[1] - c[1]

    if dx2 * dy1 == dx1 * dy2:
        return None

    t = ((x1 - x2) * dy2 + (y2 - y1) * dx2) / (dx2 * dy1 - dx1 * dy2)
    return (x1 + t * dx1, y1 + t * dy1)


