import math
def get_int():
    return int(input())
def get_int_list():
    return list(map(int, input().split()))
def get_char_list():
    return list(input())

def gcd(x, y):
    if x < y:
        return gcd(y, x)

    z = x % y
    if z == 0:
        return y
    else:
        return gcd(y, z)

