    ints = get_int_list()
    v = max(ints)
    result = [v]
    visited = set()
    visited.add(ints.index(v))
    while len(visited) < n:
        md = 0
        t = None
        for i, d in enumerate(ints):
            if i in visited:
                continue
            cd = gcd(v, d)
            if cd > md:
                md = cd
                t = i

        v = md
        result.append(ints[t])
        visited.add(t)
    print(*result)

