class Solution:
    def __init__(self):
        pass

    def solve_and_print(self):
        d, c = defaultdict(int), []
        for _ in range(int(input())):
            x, y = [int(x) for x in input().split()]
            c += [x, y]
            d[x] += y
            d[y] += x
        a, b = [q for q, k in Counter(c).items() if k == 1]
        q = 0
        while a != b:
            print(a, end=' ')
            q, a = a, d[a] - q
        print(a, end=' ')

