def gett(x,y):
    a=V[0][0]
    b=V[0][1]
    r=V[0][2]
    A=x[0]**2+y[0]**2
    B=2*x[0]*(x[1]-a)+2*y[0]*(y[1]-b)-r*r
    C=(x[1]-a)**2+(y[1]-b)**2
    if A==0:
        if B==0:
            print()
            exit(0)
        else:
            return C/B
    delta=B**2-4*A*C
    if delta<0:
        print()
        exit(0)
    t1=(-B+delta**(1/2))/(2*A)
    t2=(-B-delta**(1/2))/(2*A)
    if min(t1,t2)>0:
        return min(t1,t2)
    elif max(t1,t2)<0:
        print()
        exit(0)
    else:
        return max(t1,t2)
