from __future__ import division, print_function
_interactive = False

def main():
    MAX = 1000000
    h, v = input_as_list()
    hs = input_as_matrix(h, 3)
    vs = input_as_matrix(v, 3)

    hs += [(0, 0, MAX), (MAX, 0, MAX)]
    vs += [(0, 0, MAX), (MAX, 0, MAX)]

    # Event types
    VST, H, VEN = (0, 1, 2)
    events = []
    for y, l, r in hs:
        events += [(y, H, (l, r))]

    for x, l, r in vs:
        events += [(l, VST, x)]
        events += [(r, VEN, x)]

    events.sort()
    debug_print(events)

    st = SegmentTree([0]*MAX, func=lambda x, y: x+y)
    newv = SortedList()
    ans = 0

    for y, t, d in events:
        if t == VST:
            newv.add(d)
        elif t == H:
            l, r = d
            cnt = st.query(l, r+1)
            ans += max(0, cnt-1)

            if l == 0:
                pos = newv.bisect_right(r)
                for _ in range(pos):
                    x = newv.pop(0)
                    st[x] = 1
            else:
                pos = newv.bisect_left(l)
                while len(newv) > pos:
                    x = newv.pop()
                    st[x] = 1
        elif t == VEN:
            newv.discard(d)
            st[d] = 0

    print(ans)


