  for i in range(1, n+1):
    cost[i], label[i], target[i] = input3()
    z += (label[i] == 0)
    o += (label[i] == 1)

    tz += (target[i] == 0)
    to += (target[i] == 1)

  adj = {}
  for i in range(n-1):
    u, v = input2()
    if u not in adj:
      adj[u] = []
    if v not in adj:
      adj[v] = []

    adj[u].append(v)
    adj[v].append(u)


  if (tz != z or o != to):
    print(-1)
    exit()
  dfs1(1, -1)

  # for i in range(1, n+1):
  #   print(data[i], cost[i])

  global res
  res = 0
  call(1, -1)
  print(res)
  pass

