from math import cos,pi

def g(t):
	return t+cos(t)

def solve(y):
	assert(y>=1 and y<2*pi+1)
	low = 0.
	high = 2*pi+1
	for k in range(64):
		mid = (low+high)/2
		if g(mid) > y:
			high = mid
		else:
			low = mid
	return low

def bestTime(s,f,r,v):
	m = int((2.+float(f-s)/r)/pi-0.1)
	if (m%2 == 0): m += 1
	res = None
	for i in range(3):
		try:
			t = solve((m*pi-float(f-s)/r)/2)
			cand = (m*pi-2*t)*r/v
			if res==None or cand < res:
					res = cand
		except:
			pass
		m += 2
	return res

