from collections import deque
def main():
    def gcd(a,b):
        if a<b:
            a,b=b,a
        while b:
            a,b=b,a%b
        return a

    n=int(input())
    val=list(map(int,input().split()))
    gcds=[ {} for _ in range(n) ]
    edges={}
    for i in range(n-1):
        u,v=map(int,input().split())
        if u not in edges:
            edges[u]=[v]
        else :
            edges[u].append(v)
        if v not in edges:
            edges[v]=[u]
        else :
            edges[v].append(u)
    visited=[0]*n

    q=deque()
    q.append(1)
    visited[0]=1
    mod=10**9+7
    result=0
    while q:
        u=q.popleft()
        x=val[u-1]
        if x not in gcds[u-1]:
            gcds[u-1][x]=1
        else :
            gcds[u-1][x]+=1
        for k in gcds[u-1]:
            result=(result+gcds[u-1][k]*k)%mod
        for v in edges[u]:
            if visited[v-1]==0:
                temp=val[v-1]
                for item in gcds[u-1]:
                    a=gcd(item,temp)
                    if a not in gcds[v-1]:
                        gcds[v-1][a]=gcds[u-1][item]
                    else :
                        gcds[v-1][a]+=gcds[u-1][item]
                visited[v-1]=1
                q.append(v)
    print(result)


