def calc(size, r):
	l = 1

	while l+1 < r:
		v = (l + r) / 2
		edges = v * (v-1) / 2
		if v % 2 == 0:
			edges += v / 2 - 1
		if edges < size:
			l = v
		else:
			r = v
	return l

