# pylint: disable=redefined-builtin, ungrouped-imports
from __future__ import print_function
from bisect import bisect_left, bisect_right, insort
from collections import Sequence, MutableSequence
from functools import wraps
from itertools import chain, repeat, starmap
from math import log as log_e
import operator as op
from operator import iadd, add
from functools import reduce
from _dummy_thread import get_ident

def recursive_repr(func):
    repr_running = set()
    @wraps(func)
    def wrapper(self):
        "Return ellipsis on recursive re-entry to function."
        key = id(self), get_ident()
        if key in repr_running:
            return '...'
        repr_running.add(key)
        try:
            return func(self)
        finally:
            repr_running.discard(key)
    return wrapper
class SortedList(MutableSequence):
    def __init__(self, iterable=None, load=1000):
        self._len = 0
        self._lists = []
        self._maxes = []
        self._index = []
        self._load = load
        self._twice = load * 2
        self._half = load >> 1
        self._offset = 0
        if iterable is not None:
            self._update(iterable)
    def __new__(cls, iterable=None, key=None, load=1000):
        if key is None:
            return object.__new__(cls)
        else:
            if cls is SortedList:
                return SortedListWithKey(iterable=iterable, key=key, load=load)
            else:
                raise TypeError('inherit SortedListWithKey for key argument')
    def clear(self):
        self._len = 0
        del self._lists[:]
        del self._maxes[:]
        del self._index[:]
    _clear = clear
    def add(self, val):
        _lists = self._lists
        _maxes = self._maxes
        if _maxes:
            pos = bisect_right(_maxes, val)
            if pos == len(_maxes):
                pos -= 1
                _lists[pos].append(val)
                _maxes[pos] = val
            else:
                insort(_lists[pos], val)
            self._expand(pos)
        else:
            _lists.append([val])
            _maxes.append(val)
        self._len += 1
    def _expand(self, pos):
        _lists = self._lists
        _index = self._index
        if len(_lists[pos]) > self._twice:
            _maxes = self._maxes
            _load = self._load
            _lists_pos = _lists[pos]
            half = _lists_pos[_load:]
            del _lists_pos[_load:]
            _maxes[pos] = _lists_pos[-1]
            _lists.insert(pos + 1, half)
            _maxes.insert(pos + 1, half[-1])
            del _index[:]
        else:
            if _index:
                child = self._offset + pos
                while child:
                    _index[child] += 1
                    child = (child - 1) >> 1
                _index[0] += 1
    def update(self, iterable):
        _lists = self._lists
        _maxes = self._maxes
        values = sorted(iterable)
        if _maxes:
            if len(values) * 4 >= self._len:
                values.extend(chain.from_iterable(_lists))
                values.sort()
                self._clear()
            else:
                _add = self.add
                for val in values:
                    _add(val)
                return
        _load = self._load
        _lists.extend(values[pos:(pos + _load)]
                      for pos in range(0, len(values), _load))
        _maxes.extend(sublist[-1] for sublist in _lists)
        self._len = len(values)
        del self._index[:]
    _update = update
    def __contains__(self, val):
        _maxes = self._maxes
        if not _maxes:
            return False
        pos = bisect_left(_maxes, val)
        if pos == len(_maxes):
            return False
        _lists = self._lists
        idx = bisect_left(_lists[pos], val)
        return _lists[pos][idx] == val
    def discard(self, val):
        _maxes = self._maxes
        if not _maxes:
            return
        pos = bisect_left(_maxes, val)
        if pos == len(_maxes):
            return
        _lists = self._lists
        idx = bisect_left(_lists[pos], val)
        if _lists[pos][idx] == val:
            self._delete(pos, idx)
    def remove(self, val):
        _maxes = self._maxes
        if not _maxes:
            raise ValueError('{0} not in list'.format(repr(val)))
        pos = bisect_left(_maxes, val)
        if pos == len(_maxes):
            raise ValueError('{0} not in list'.format(repr(val)))
        _lists = self._lists
        idx = bisect_left(_lists[pos], val)
        if _lists[pos][idx] == val:
            self._delete(pos, idx)
        else:
            raise ValueError('{0} not in list'.format(repr(val)))
    def _delete(self, pos, idx):
        _lists = self._lists
        _maxes = self._maxes
        _index = self._index
        _lists_pos = _lists[pos]
        del _lists_pos[idx]
        self._len -= 1
        len_lists_pos = len(_lists_pos)
        if len_lists_pos > self._half:
            _maxes[pos] = _lists_pos[-1]
            if _index:
                child = self._offset + pos
                while child > 0:
                    _index[child] -= 1
                    child = (child - 1) >> 1
                _index[0] -= 1
        elif len(_lists) > 1:
            if not pos:
                pos += 1
            prev = pos - 1
            _lists[prev].extend(_lists[pos])
            _maxes[prev] = _lists[prev][-1]
            del _lists[pos]
            del _maxes[pos]
            del _index[:]
            self._expand(prev)
        elif len_lists_pos:
            _maxes[pos] = _lists_pos[-1]
        else:
            del _lists[pos]
            del _maxes[pos]
            del _index[:]
    def _loc(self, pos, idx):
        if not pos:
            return idx
        _index = self._index
        if not len(_index):
            self._build_index()
        total = 0
        # Increment pos to point in the index to len(self._lists[pos]).
        pos += self._offset
        # Iterate until reaching the root of the index tree at pos = 0.
        while pos:
            # Right-child nodes are at odd indices. At such indices
            # account the total below the left child node.
            if not pos & 1:
                total += _index[pos - 1]
            # Advance pos to the parent node.
            pos = (pos - 1) >> 1
        return total + idx
    def _pos(self, idx):
        if idx < 0:
            last_len = len(self._lists[-1])
            if (-idx) <= last_len:
                return len(self._lists) - 1, last_len + idx
            idx += self._len
            if idx < 0:
                raise IndexError('list index out of range')
        elif idx >= self._len:
            raise IndexError('list index out of range')
        if idx < len(self._lists[0]):
            return 0, idx
        _index = self._index
        if not _index:
            self._build_index()
        pos = 0
        child = 1
        len_index = len(_index)
        while child < len_index:
            index_child = _index[child]
            if idx < index_child:
                pos = child
            else:
                idx -= index_child
                pos = child + 1
            child = (pos << 1) + 1
        return (pos - self._offset, idx)
    def _build_index(self):
        row0 = list(map(len, self._lists))
        if len(row0) == 1:
            self._index[:] = row0
            self._offset = 0
            return
        head = iter(row0)
        tail = iter(head)
        row1 = list(starmap(add, zip(head, tail)))
        if len(row0) & 1:
            row1.append(row0[-1])
        if len(row1) == 1:
            self._index[:] = row1 + row0
            self._offset = 1
            return
        size = 2 ** (int(log_e(len(row1) - 1, 2)) + 1)
        row1.extend(repeat(0, size - len(row1)))
        tree = [row0, row1]
        while len(tree[-1]) > 1:
            head = iter(tree[-1])
            tail = iter(head)
            row = list(starmap(add, zip(head, tail)))
            tree.append(row)
        reduce(iadd, reversed(tree), self._index)
        self._offset = size * 2 - 1
    def __delitem__(self, idx):
        if isinstance(idx, slice):
            start, stop, step = idx.indices(self._len)
            if step == 1 and start < stop:
                if start == 0 and stop == self._len:
                    return self._clear()
                elif self._len <= 8 * (stop - start):
                    values = self._getitem(slice(None, start))
                    if stop < self._len:
                        values += self._getitem(slice(stop, None))
                    self._clear()
                    return self._update(values)
            indices = range(start, stop, step)
            # Delete items from greatest index to least so
            # that the indices remain valid throughout iteration.
            if step > 0:
                indices = reversed(indices)
            _pos, _delete = self._pos, self._delete
            for index in indices:
                pos, idx = _pos(index)
                _delete(pos, idx)
        else:
            pos, idx = self._pos(idx)
            self._delete(pos, idx)
    _delitem = __delitem__
    def __getitem__(self, idx):
        _lists = self._lists
        if isinstance(idx, slice):
            start, stop, step = idx.indices(self._len)
            if step == 1 and start < stop:
                if start == 0 and stop == self._len:
                    return reduce(iadd, self._lists, [])
                start_pos, start_idx = self._pos(start)
                if stop == self._len:
                    stop_pos = len(_lists) - 1
                    stop_idx = len(_lists[stop_pos])
                else:
                    stop_pos, stop_idx = self._pos(stop)
                if start_pos == stop_pos:
                    return _lists[start_pos][start_idx:stop_idx]
                prefix = _lists[start_pos][start_idx:]
                middle = _lists[(start_pos + 1):stop_pos]
                result = reduce(iadd, middle, prefix)
                result += _lists[stop_pos][:stop_idx]
                return result
            if step == -1 and start > stop:
                result = self._getitem(slice(stop + 1, start + 1))
                result.reverse()
                return result
            # Return a list because a negative step could
            # reverse the order of the items and this could
            # be the desired behavior.
            indices = range(start, stop, step)
            return list(self._getitem(index) for index in indices)
        else:
            if self._len:
                if idx == 0:
                    return _lists[0][0]
                elif idx == -1:
                    return _lists[-1][-1]
            else:
                raise IndexError('list index out of range')
            if 0 <= idx < len(_lists[0]):
                return _lists[0][idx]
            len_last = len(_lists[-1])
            if -len_last < idx < 0:
                return _lists[-1][len_last + idx]
            pos, idx = self._pos(idx)
            return _lists[pos][idx]
    _getitem = __getitem__
    def _check_order(self, idx, val):
        _len = self._len
        _lists = self._lists
        pos, loc = self._pos(idx)
        if idx < 0:
            idx += _len
        # Check that the inserted value is not less than the
        # previous value.
        if idx > 0:
            idx_prev = loc - 1
            pos_prev = pos
            if idx_prev < 0:
                pos_prev -= 1
                idx_prev = len(_lists[pos_prev]) - 1
            if _lists[pos_prev][idx_prev] > val:
                msg = '{0} not in sort order at index {1}'.format(repr(val), idx)
                raise ValueError(msg)
        # Check that the inserted value is not greater than
        # the previous value.
        if idx < (_len - 1):
            idx_next = loc + 1
            pos_next = pos
            if idx_next == len(_lists[pos_next]):
                pos_next += 1
                idx_next = 0
            if _lists[pos_next][idx_next] < val:
                msg = '{0} not in sort order at index {1}'.format(repr(val), idx)
                raise ValueError(msg)
    def __setitem__(self, index, value):
        _lists = self._lists
        _maxes = self._maxes
        _check_order = self._check_order
        _pos = self._pos
        if isinstance(index, slice):
            start, stop, step = index.indices(self._len)
            indices = range(start, stop, step)
            if step != 1:
                if not hasattr(value, '__len__'):
                    value = list(value)
                indices = list(indices)
                if len(value) != len(indices):
                    raise ValueError(
                        'attempt to assign sequence of size {0}'
                        ' to extended slice of size {1}'
                        .format(len(value), len(indices)))
                # Keep a log of values that are set so that we can
                # roll back changes if ordering is violated.
                log = []
                _append = log.append
                for idx, val in zip(indices, value):
                    pos, loc = _pos(idx)
                    _append((idx, _lists[pos][loc], val))
                    _lists[pos][loc] = val
                    if len(_lists[pos]) == (loc + 1):
                        _maxes[pos] = val
                try:
                    # Validate ordering of new values.
                    for idx, oldval, newval in log:
                        _check_order(idx, newval)
                except ValueError:
                    # Roll back changes from log.
                    for idx, oldval, newval in log:
                        pos, loc = _pos(idx)
                        _lists[pos][loc] = oldval
                        if len(_lists[pos]) == (loc + 1):
                            _maxes[pos] = oldval
                    raise
            else:
                if start == 0 and stop == self._len:
                    self._clear()
                    return self._update(value)
                # Test ordering using indexing. If the given value
                # isn't a Sequence, convert it to a tuple.
                if not isinstance(value, Sequence):
                    value = tuple(value) # pylint: disable=redefined-variable-type
                # Check that the given values are ordered properly.
                iterator = range(1, len(value))
                if not all(value[pos - 1] <= value[pos] for pos in iterator):
                    raise ValueError('given sequence not in sort order')
                # Check ordering in context of sorted list.
                if not start or not len(value):
                    # Nothing to check on the lhs.
                    pass
                else:
                    if self._getitem(start - 1) > value[0]:
                        msg = '{0} not in sort order at index {1}'.format(repr(value[0]), start)
                        raise ValueError(msg)
                if stop == len(self) or not len(value):
                    # Nothing to check on the rhs.
                    pass
                else:
                    # "stop" is exclusive so we don't need
                    # to add one for the index.
                    if self._getitem(stop) < value[-1]:
                        msg = '{0} not in sort order at index {1}'.format(repr(value[-1]), stop)
                        raise ValueError(msg)
                # Delete the existing values.
                self._delitem(index)
                # Insert the new values.
                _insert = self.insert
                for idx, val in enumerate(value):
                    _insert(start + idx, val)
        else:
            pos, loc = _pos(index)
            _check_order(index, value)
            _lists[pos][loc] = value
            if len(_lists[pos]) == (loc + 1):
                _maxes[pos] = value
    def __iter__(self):
        return chain.from_iterable(self._lists)
    def __reversed__(self):
        return chain.from_iterable(map(reversed, reversed(self._lists)))
    def islice(self, start=None, stop=None, reverse=False):
        _len = self._len
        if not _len:
            return iter(())
        start, stop, _ = slice(start, stop).indices(self._len)
        if start >= stop:
            return iter(())
        _pos = self._pos
        min_pos, min_idx = _pos(start)
        if stop == _len:
            max_pos = len(self._lists) - 1
            max_idx = len(self._lists[-1])
        else:
            max_pos, max_idx = _pos(stop)
        return self._islice(min_pos, min_idx, max_pos, max_idx, reverse)
    def _islice(self, min_pos, min_idx, max_pos, max_idx, reverse):
        _lists = self._lists
        if min_pos > max_pos:
            return iter(())
        elif min_pos == max_pos and not reverse:
            return iter(_lists[min_pos][min_idx:max_idx])
        elif min_pos == max_pos and reverse:
            return reversed(_lists[min_pos][min_idx:max_idx])
        elif min_pos + 1 == max_pos and not reverse:
            return chain(_lists[min_pos][min_idx:], _lists[max_pos][:max_idx])
        elif min_pos + 1 == max_pos and reverse:
            return chain(
                reversed(_lists[max_pos][:max_idx]),
                reversed(_lists[min_pos][min_idx:]),
            )
        elif not reverse:
            return chain(
                _lists[min_pos][min_idx:],
                chain.from_iterable(_lists[(min_pos + 1):max_pos]),
                _lists[max_pos][:max_idx],
            )
        else:
            temp = map(reversed, reversed(_lists[(min_pos + 1):max_pos]))
            return chain(
                reversed(_lists[max_pos][:max_idx]),
                chain.from_iterable(temp),
                reversed(_lists[min_pos][min_idx:]),
            )
    def irange(self, minimum=None, maximum=None, inclusive=(True, True),
               reverse=False):
        _maxes = self._maxes
        if not _maxes:
            return iter(())
        _lists = self._lists
        # Calculate the minimum (pos, idx) pair. By default this location
        # will be inclusive in our calculation.
        if minimum is None:
            min_pos = 0
            min_idx = 0
        else:
            if inclusive[0]:
                min_pos = bisect_left(_maxes, minimum)
                if min_pos == len(_maxes):
                    return iter(())
                min_idx = bisect_left(_lists[min_pos], minimum)
            else:
                min_pos = bisect_right(_maxes, minimum)
                if min_pos == len(_maxes):
                    return iter(())
                min_idx = bisect_right(_lists[min_pos], minimum)
        # Calculate the maximum (pos, idx) pair. By default this location
        # will be exclusive in our calculation.
        if maximum is None:
            max_pos = len(_maxes) - 1
            max_idx = len(_lists[max_pos])
        else:
            if inclusive[1]:
                max_pos = bisect_right(_maxes, maximum)
                if max_pos == len(_maxes):
                    max_pos -= 1
                    max_idx = len(_lists[max_pos])
                else:
                    max_idx = bisect_right(_lists[max_pos], maximum)
            else:
                max_pos = bisect_left(_maxes, maximum)
                if max_pos == len(_maxes):
                    max_pos -= 1
                    max_idx = len(_lists[max_pos])
                else:
                    max_idx = bisect_left(_lists[max_pos], maximum)
        return self._islice(min_pos, min_idx, max_pos, max_idx, reverse)
    def __len__(self):
        return self._len
    def bisect_left(self, val):
        _maxes = self._maxes
        if not _maxes:
            return 0
        pos = bisect_left(_maxes, val)
        if pos == len(_maxes):
            return self._len
        idx = bisect_left(self._lists[pos], val)
        return self._loc(pos, idx)
    def bisect_right(self, val):
        _maxes = self._maxes
        if not _maxes:
            return 0
        pos = bisect_right(_maxes, val)
        if pos == len(_maxes):
            return self._len
        idx = bisect_right(self._lists[pos], val)
        return self._loc(pos, idx)
    bisect = bisect_right
    _bisect_right = bisect_right
    def count(self, val):
        _maxes = self._maxes
        if not _maxes:
            return 0
        pos_left = bisect_left(_maxes, val)
        if pos_left == len(_maxes):
            return 0
        _lists = self._lists
        idx_left = bisect_left(_lists[pos_left], val)
        pos_right = bisect_right(_maxes, val)
        if pos_right == len(_maxes):
            return self._len - self._loc(pos_left, idx_left)
        idx_right = bisect_right(_lists[pos_right], val)
        if pos_left == pos_right:
            return idx_right - idx_left
        right = self._loc(pos_right, idx_right)
        left = self._loc(pos_left, idx_left)
        return right - left
