def f():
    n = int(input())
    neibors = [set() for i in range(n+1)]
    for i in range(n-1):
        a, b = [int(s) for s in input().split()]
        neibors[a].add(b)
        neibors[b].add(a)
    visited = [0]*(n+1)
    rem = [n]

    def bfs(u,v,w):
        q = collections.deque()
        if u != w:
            visited[u] = 1
            rem[0] -= 1
            q.append(u)
        if v != w:
            visited[v] = 1
            rem[0] -= 1
            q.append(v)
        while q:
            node = q.popleft()
            for nb in neibors[node]:
                if (nb != w) and (not visited[nb]):
                    visited[nb] = 1
                    rem[0] -= 1
                    q.append(nb)

    while rem[0] > 1:
        for i in range(1,n+1):
            if not visited[i]:
                u = i
                break
        for i in range(u+1,n+1):
            if not visited[i]:
                v = i
                break
        if (v in neibors[u]) and rem[0] > 2:
            for i in range(v+1,n+1):
                if not visited[i]:
                    x = i
                    break
            if x in neibors[u]:
                u = x
            else:
                v = x       
        w = getAnc(u,v)
        bfs(u,v,w)
    for i in range(1,n+1):
        if not visited[i]:
            print('! {}'.format(i))
            return


