def solve(n, s):
	swaps = []
	for i in range(n-1):
		if s[i] == '0' and s[i] == s[i+1]:
			swaps.append(i+1)
			s[i] = '1'
			s[i+1] = '1'
	if s.count('0')%2 == 1:
		return [-1]
	i = 0
	while i < n:
		if s[i] == '0':
			j = s.index('0', i+1)
			swaps += list(range(i+1, j+1))
			i = j+1
		else:
			i += 1
	return swaps

