def add_subs(num, freq):
  used = set()

  for l in range(1, len(num) + 1):
    for i in range(len(num) - l + 1):
      end = i + l
      sub = num[i : end]

      if sub not in used:
        used.add(sub)
        if sub not in freq:
          freq[sub] = 1
        else:
          freq[sub] += 1

def count_subs(nums):
  freq = {}
  for n in nums:
    add_subs(n, freq)
  return freq

def find_sub(num, freq):
  for l in range(1, len(num)):
    for i in range(len(num) - l + 1):
      end = i + l
      sub = num[i : end]
      if freq[sub] == 1:
        return sub
  return num

def main():
  n = int(input())
  nums = [input() for i in range(n)]

  freq = count_subs(nums)
  for number in nums:
    print(find_sub(number, freq))

