import sys





def numbers_of_one(n):
	res=0

	while n:
		if n&1:res+=1
		n>>=1
	return res




def brute_force(l,r,k):
	numbers=[i for i in range(l,r+1)]
	n=len(numbers)
	aux=r<<2
	res=[]
	# import ipdb;ipdb.set_trace()
	for subset in range(1,1<<(r-l+1)):
		if numbers_of_one(subset)<=k:
			tmp,tmp_l=0,[]
			for j in range(n):
				if 1<<j&subset:
					tmp^=numbers[j]
					tmp_l.append(numbers[j])
			if tmp<aux:
				aux=tmp
				res=tmp_l
	return aux,len(res),res







