class multiset:
	def __init__(self):
		self.contenido = dict()
		self.len = 0

	def add(self, x):
		self.contenido[x] = self.contenido.get(x, 0)+1
		self.len += 1

	def remove(self, x):
		valor = self.contenido.get(x, 1)-1
		if valor == 0:
			del self.contenido[x]
		else:
			self.contenido[x] = valor
		self.len -= 1

	def pop(self):
		x = next(iter(self.contenido.keys()))
		self.remove(x)
		return x

	def __len__(self):
		return self.len

	def __str__(self):
		return str(self.contenido)

