            t[i][j]=max(t[i][j-1],t[i+(1<<(j-1))][j-1])

def query(p,q):
    p,q=int(p),int(q)
    log=int(math.log2(q-p+1))
    m=t[p][log]
    n=t[q-(1<<log)+1][log]
    return max(m,n)

