def dfs(v, visited, edges, colors):
    st = [v]
    visited.add(v)
    comp = []
    cols = dict()
    while st:
        ver = st.pop()
        comp.append(colors[ver])
        if ver in edges:
            for i in edges[ver]:
                if i not in visited:
                    st.append(i)
                    visited.add(i)
    for i in comp:
        if i not in cols:
            cols[i] = 1
        else:
            cols[i] += 1
    max_c = 0
    for i in cols:
        if cols[i] > max_c:
            max_c = cols[i]
    return len(comp) - max_c



