area = sum(map(lambda x: cross(x[0], x[1]), zip(polygon, polygon[1:] + polygon[:1])))
if (area < 0): polygon.reverse()

for i in range(m):
    x1, y1, x2, y2 = map(float, input().split())
    solve(polygon, Vector(x1, y1), Vector(x2, y2))

