    if cycle(edges,n):
        print -1
        return

    dp = [[0 for i in xrange(26)] for j in xrange(n+1)]
    visited = set()
    for i in incoming:
        if i not in visited:
            dfs(dp,i,edges,s,visited)

    ans = 0
    for i in incoming:
        ans = max(ans,max(dp[i]))

    print ans


