def getn(v, k = 1):
    res = []
    while k <= v:
        res.append(v)
        v //= 2
    return res

def getp(arr):
    res = []
    for i in range(len(arr) - 1):
        res.append((arr[i], arr[i + 1]))
    return res

def gets(u, v):
    resu, resv = getn(u), getn(v)
    for i in resv:
        if i in resu:
            return getp(getn(u, i)) + getp(getn(v, i))

