def main():
    t = 1

    rr = []
    for _ in range(t):
        n = I()

        k = 1
        while n % 2 == 0 and n != 4:
            k *= 2
            n //= 2

        if n == 1:
            rr.append(-1)
        elif n == 4:
            rr.append(JA([3*k,5*k], " "))
        else:
            t = n**2 // 2
            rr.append(JA([t*k,(t+1)*k], " "))

    return JA(rr, "\n")


