def main():
    from math import gcd
    input()
    aa = list(map(int, input().split()))
    g = r = t = 0
    while aa and g != 1:
        a = aa.pop()
        if t:
            r += 2 - (a & 1)
            t = 0
        else:
            t = (a & 1) * 2
        g = gcd(a, g)
    for a in reversed(aa):
        if t:
            r += 2 - (a & 1)
            t = 0
        else:
            t = (a & 1) * 2
    print("YES", (r + t) * (g < 2), sep='\n')


