for _ in range(t):
    n,m = map(int,input().split())
    connectionList = []
    for _ in range(n):
        connectionList.append([])
    for _ in range(m):
        u,v = map(int,input().split())
        connectionList[u-1].append(v-1)
        connectionList[v-1].append(u-1)
    DFSLevel = [-1] * n
    DFSParent = [-1] * n
    vertexStack = []
    vertexStack.append((0,1,-1)) # vertex depth and parent
    while vertexStack:
        vertex,depth,parent = vertexStack.pop()
        if DFSLevel[vertex] != -1:
            continue
        DFSLevel[vertex] = depth
        DFSParent[vertex] = parent
        for nextV in connectionList[vertex]:
            if DFSLevel[nextV] == -1:
                vertexStack.append((nextV,depth + 1,vertex))
    if max(DFSLevel) >= n//2 + n % 2:
        for i in range(n):
            if DFSLevel[i] >= (n//2 + n%2):
                break
        longPath = [str(i + 1)]
        while DFSParent[i] != -1:
            longPath.append(str(DFSParent[i] + 1))
            i = DFSParent[i]
        print("PATH")
        print(len(longPath))
        print(" ".join(longPath))
    else:
        levelWithVertex = list(enumerate(DFSLevel))
        levelWithVertex.sort(key = lambda x: x[1])
        i = 0
        pair = []
        while i < len(levelWithVertex) - 1:
            if levelWithVertex[i][1] == levelWithVertex[i + 1][1]:
                pair.append([levelWithVertex[i][0],levelWithVertex[i + 1][0]])
                i += 2
            else:
                i += 1
        print("PAIRING")
        print(len(pair))
        for elem in pair:
            print(str(elem[0] + 1)+" "+str(elem[1] + 1))

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def lcm(a, b):
    return a // gcd(a, b) * b

def cal((f1, k1), (f2, k2)):
    if f1 > f2:
        f1, k1, f2, k2 = f2, k2, f1, k1
    A = (f1 - f2) % k2
    B = 0
    x1 = 0
    k11 = k1 % k2
    k1x1 = 0
    while B != A and k1x1 <= f1:
        if B < A:
            dx1 = (A - B) // k11
        else:
            dx1 = (A + k2 - B) // k11
        dx1 = max(dx1, 1)
        B = (B + k11 * dx1) % k2
        x1 += dx1
        k1x1 += k1 * dx1
    f = f1 - k1x1
    if f <= 0:
        return (0, 1)
    k = lcm(k1, k2)
    return (f, k)

def cals(fks):
    fk0 = None
    for fk in fks:
        if fk0 is None:
            fk0 = fk
        else:
            # print fk, fk0
            fk0 = cal(fk0, fk)
        if fk0[0] == 0:
            return fk0
    return fk0

def solve():
    n = int(raw_input())
    a = map(int, raw_input().split())
    chs = [[] for i in xrange(n)]
    for i in xrange(n-1):
        u, v = map(int, raw_input().split())
        u, v = u - 1, v - 1
        chs[u].append(v)
        chs[v].append(u)

    p = []
    stk = [0]
    vis = {0}
    chs1 = [[] for i in xrange(n)]
    while stk:
        u = stk.pop()
        p.append(u)
        for v in chs[u]:
            if not v in vis:
                stk.append(v)
                chs1[u].append(v)
                vis.add(v)
    chs = chs1
    p.reverse()

    ws = [0] * n
    for u in p:
        ws[u] = a[u] + sum(ws[v] for v in chs[u])

    fks = [None] * n
    for u in p:
        if not chs[u]:
            fks[u] = (a[u], 1)
        else:
            f, k = cals(fks[v] for v in chs[u])
            nc = len(chs[u])
            fks[u] = (a[u] + f * nc, k * nc)
    # print chs
    # print zip(a, fks)
    return ws[0] - fks[0][0]

