from sys import stdin
from itertools import repeat
from collections import defaultdict
def main():
    n, y1 = map(int, stdin.readline().split())
    a = map(int, stdin.readline().split(), repeat(10, n))
    m, y2 = map(int, stdin.readline().split())
    b = map(int, stdin.readline().split(), repeat(10, m))
    ans = 2
    d = defaultdict(int)
    for x in a:
        d[x] += 1
    for x in b:
        d[x] += 1
    t = max(d.viewvalues())
    if ans < t:
        ans = t
    ca = [0, 0]
    cb = [0, 0]
    for x in a:
        ca[x&1] += 1
    for x in b:
        cb[x&1] += 1
    for j in xrange(2):
        t = ca[j] + cb[j^1]
        if ans < t:
            ans = t
    for i in xrange(1, 30):
        da = defaultdict(int)
        db = defaultdict(int)
        k = (2 << i) - 1
        h = 1 << i
        for x in a:
            da[x&k] += 1
        for x in b:
            db[x&k] += 1
        for i, x in da.viewitems():
            if i ^ h in db:
                t = x + db[i^h]
                if ans < t:
                    ans = t
    print ans
main()

