    current_price = 0
    ans = len(string)
    for i in range(len(string)-1,0,-1):
        if i == 1 or string[i-1] != string[i-2]:
            if string[i-1] == 'A':
                current_price += a
            else:
                current_price += b
            if current_price > p:
                return ans;
            else:
                ans = i
    return 1

