    bob_max = cinema_to_house + t2

    def check(d):
        c1, c2, c3 = (cinema, d), (house, bob_max-d), (shop, alice_max-d-shop_to_house)
        for i in range(3):
            status = intersect(c1, c2)
            if status == 0:
                return False
            if status == 1:
