    memor = {}
    def mexor(val, i):
        if val <= 0:
            return 0
        if ((val, i)) not in memor:
            A = []
            A.append(mexor(val - x, 0))
            if i != 1:
                A.append(mexor(val - y, 1))
            if i != 2:
                A.append(mexor(val - z, 2))
            if 0 not in A:
                ans = 0
            elif 1 not in A:
                ans = 1
            elif 2 not in A:
                ans = 2
            else:
                ans = 3
            memor[(val, i)] = ans
        return memor[(val, i)]

    AA = [mexor(i, 0) for i in range(250)]
    BB = [mexor(i, 1) for i in range(250)]
    CC = [mexor(i, 2) for i in range(250)]

    aper = 70
    while aper and AA[125 : 125 + aper] != AA[125 + aper : 125 + 2 * aper]:
        aper -= 1
    bper = 70
    while bper and BB[125 : 125 + bper] != BB[125 + bper : 125 + 2 * bper]:
        bper -= 1
    cper = 70
    while cper and CC[125 : 125 + cper] != CC[125 + cper : 125 + 2 * cper]:
        cper -= 1

    def mexor(val, i):
        if val <= 0:
            return 0
        if i == 0:
            if val < 250:
                return AA[val]
            else:
                return AA[125 + (val - 125) % aper]
        elif i == 1:
            if val < 250:
                return BB[val]
            else:
                return BB[125 + (val - 125) % bper]
        else:
            if val < 250:
                return CC[val]
            else:
                return CC[125 + (val - 125) % cper]

    xor = 0
    for a in A:
        xor ^= mexor(a, 0)

    ways = 0
    for a in A:
        newxor = xor ^ mexor(a, 0)

        if mexor(a - x, 0) == newxor:
            ways += 1
        if mexor(a - y, 1) == newxor:
            ways += 1
        if mexor(a - z, 2) == newxor:
            ways += 1
    print ways

def my_solve(n, m, graph, mask):
	if do_dfs_bool(n,graph,mask.copy()):
		c = get_cyclic(n, graph, mask)
		for u,v in c:
			graph[u].remove(v)
			if not do_dfs_bool(n,graph,mask.copy()):
				return 'YES'
			graph[u].append(v)
		return "NO"
	return "YES"

def get_cyclic(n, graph, mask):
	c,v = do_dfs(n,graph,mask)
	path = []
	i = 0
	begin = False
	if c:
		for u in c.keys():
			if c[u] == v:
				begin = True
				path.append((c[u],u))
			elif begin:
				path.append((c[u],u))
		tmp = list(c.keys())
		if len(tmp):
			path.append((tmp[-1],v))
	return path

def do_dfs_bool(n, graph, mask):
	colors = [0]*(n+5)
	for u in graph.keys():
		if not u in mask.keys():
			if dfs_bool(u,graph,mask,colors):
				return True
	return False


def dfs_bool(u, graph, mask,colors):
	colors[u] = 1
	mask[u] = True
	for v in graph[u]:
		if colors[v] == 1:
			return True
		if colors[v] == 0:
			if dfs_bool(v,graph,mask,colors):				
				return True
	colors[u] = 2
	return False

def do_dfs(n, graph, mask):
	colors = [0]*(n+5)
	c = {}
	for u in graph.keys():
		if not u in mask.keys():
			c = {}
			p, v = dfs(u,graph,mask,c,colors)
			if p and v:
				return (p,v)


def dfs(u, graph, mask, c, colors):
	colors[u] = 1
	for v in graph[u]:
		if colors[v] == 1:
			return (c, v)
		if colors[v] == 0:
			c[v] = u
			p,w = dfs(v,graph,mask,c,colors)
			if w:
				return (p,w)
	colors[u] = 2
	if len(c) > 0:
		if u in c.keys():
			del c[u]
	return (c, None)

def test(n, m, edges):
	graph = {}
	mask = {}
	for u,v in edges:
		if u not in graph.keys():
			graph[u] = []
		graph[u].append(v)
		if v not in graph.keys():
			graph[v] = []
	return my_solve(n, m, graph, mask)


