    # print(time, maxTime)
    for i, j in pairs:
        collidePair(i, j)
        # print(i, balls[i], j, balls[j])
    # print()

    maxTime -= time


for ball in balls:
    ball.move(maxTime)
    print("{:.6f}".format(ball.x))

