INF = float('inf')



def bfs(graph, start=0):
    used = [False] * len(graph)
    used[start] = True
    dist = [0] * len(graph)
    q = [start]
    for v in q:
        for w in graph[v]:
            if not used[w]:
                dist[w] = dist[v] + 1
                used[w] = True
                q.append(w)
    return dist, q[-3:]


def main():
    n, m = map(int, input().split())

    rev_graph = [set() for _ in range(n)]
    graph = [set() for _ in range(n)]
    for _ in range(m):
        u, v = map(int, input().split())
        if u == v:
            continue
        graph[u - 1].add(v - 1)
        rev_graph[v - 1].add(u - 1)


    adj = [[0] * n for _ in range(n)]
    best_to = [[0] * 3 for _ in range(n)]
    best_from = [[0] * 3 for _ in range(n)]

    for i in range(n):
        adj[i], best_from[i] = bfs(graph, i)
        _, best_to[i] = bfs(rev_graph, i)


    best_score = 0
    sol = (-1, -1, -1, -1)

    for c2 in range(n):
        for c3 in range(n):
            if not adj[c2][c3] or c2 == c3:
                continue

            for c1 in best_to[c2]:
                if c1 in [c2, c3]:
                    continue

                for c4 in best_from[c3]:
                    if c4 in [c1, c2, c3]:
                        continue

                    score = adj[c1][c2] + adj[c2][c3] + adj[c3][c4]

                    if score > best_score:
                        best_score = score
                        sol = (c1 + 1, c2 + 1, c3 + 1, c4 + 1)

    print(*sol)


# region fastio

BUFSIZE = 8192


class FastIO(IOBase):
    newlines = 0

    def __init__(self, file):
        self._fd = file.fileno()
        self.buffer = BytesIO()
        self.writable = "x" in file.mode or "r" not in file.mode
        self.write = self.buffer.write if self.writable else None

    def read(self):
        while True:
            b = os.read(self._fd, max(os.fstat(self._fd).st_size, BUFSIZE))
            if not b:
                break
            ptr = self.buffer.tell()
            self.buffer.seek(0, 2), self.buffer.write(b), self.buffer.seek(ptr)
        self.newlines = 0
        return self.buffer.read()

    def readline(self):
        while self.newlines == 0:
            b = os.read(self._fd, max(os.fstat(self._fd).st_size, BUFSIZE))
            self.newlines = b.count(b"\n") + (not b)
            ptr = self.buffer.tell()
            self.buffer.seek(0, 2), self.buffer.write(b), self.buffer.seek(ptr)
        self.newlines -= 1
        return self.buffer.readline()

    def flush(self):
        if self.writable:
            os.write(self._fd, self.buffer.getvalue())
            self.buffer.truncate(0), self.buffer.seek(0)


class IOWrapper(IOBase):
    def __init__(self, file):
        self.buffer = FastIO(file)
        self.flush = self.buffer.flush
        self.writable = self.buffer.writable
        self.write = lambda s: self.buffer.write(s.encode("ascii"))
        self.read = lambda: self.buffer.read().decode("ascii")
        self.readline = lambda: self.buffer.readline().decode("ascii")


def print(*args, **kwargs):
    """Prints the values to a stream, or to sys.stdout by default."""
    sep, file = kwargs.pop("sep", " "), kwargs.pop("file", sys.stdout)
    at_start = True
    for x in args:
        if not at_start:
            file.write(sep)
        file.write(str(x))
        at_start = False
    file.write(kwargs.pop("end", "\n"))
    if kwargs.pop("flush", False):
        file.flush()


if sys.version_info[0] < 3:
    sys.stdin, sys.stdout = FastIO(sys.stdin), FastIO(sys.stdout)
else:
    sys.stdin, sys.stdout = IOWrapper(sys.stdin), IOWrapper(sys.stdout)

input = lambda: sys.stdin.readline().rstrip("\r\n")

