        x, y = x - 1, y - 1
        target = x

        if len(s[x]) < len(s[y]):
            x, y = y,  x

        for e in s[y]:
            if e - 1 in s[x]:
                score -= 1
            if e + 1 in s[x]:
                score -= 1
        for e in s[y]:
            s[x].add(e)

        s[target] = s[x]
        ans.append(score)

    print(*ans, sep='\n')


