    b[p] = x
    pb[p] = p - N
    while p > 1:
        p, q = p / 2, p / 2 * 2
        if b[q] >= b[q+1]:
            q += 1
        b[p], pb[p] = b[q], pb[q]
def query(left, right, p = 1, L = 0, R = N):
    if right <= L or R <= left:
        return (10000, -1)
    if left <= L and R <= right:
        return (b[p], pb[p])
    mid = (L + R) / 2
    return min(query(left, right, p+p, L, mid), query(left, right, p+p+1, mid, R))

