match = 0; nonmatch = 0; count = 0
def calc_match(s, t, p):
  global match
  global nonmatch
  global count
  if p == len(s)-len(t):
    return
  if p+len(t) < len(s):
    if s[p+len(t)] == '?':
      count -= 1
    elif s[p+len(t)] == t[-1]:
      match -= 1
    else:
      nonmatch -= 1
  match, nonmatch = nonmatch, match
  if p+len(t) < len(s):
    if s[p] == '?':
      count += 1
    elif s[p] == 'a':
      match += 1
    else:
      nonmatch += 1
def init_match(s, t):
  global match
  global nonmatch
  global count
  p = len(s)-len(t)
  for i in range(len(t)):
    if s[p+i] == '?':
      count += 1
    elif s[p+i] == t[i]:
      match += 1
    else:
      nonmatch += 1
