def dfs(t, a, b, s1, s2):
    cnt = 0
    is_inf = False

    if s1 == s2:
        if s1 < t or s2 < a:
            return is_inf, 1
        else:
            cnt += 1

    if s2 >= a and s1 >= t:
        a0 = s2 % a
        if (s1-a0) % t == 0 and (s2-a0) % a == 0:
            ns1, ns2 = (s1-a0)/t, (s2-a0)/a
            if ns1 == s1 and ns2 == s2:
                if s1 == s2:
                    is_inf = True
            else:
                is_inf, val = dfs(t, a, b, ns1, ns2)
                cnt += val
        return is_inf, cnt % int(1e9+7)
    else:
        return is_inf, 0

