class DSU(object):
    def __init__(self, n):
        self.pnt = [-1] * n

    def find(self, x):
        pnt = self.pnt
        if pnt[x] == -1:
            return x
        pnt[x] = self.find(pnt[x])
        return pnt[x]

    def join(self, u, v):
        pnt = self.pnt
        u = self.find(u)
        v = self.find(v)
        if u != v:
            pnt[v] = u
            return True
        return False

    def same(self, u, v):
        u = self.find(u)
        v = self.find(v)
        return u == v

