class Node:
    def __init__(self, index):
        self.left = index - 1
        self.right = index + 1
        self.pair = -1

if __name__ == "__main__":
    n, m, p = map(int, input().split())
    brackets = input()
    operations = input()

    nodes = [Node(i) for i in range(n + 1)]
    stack = []

    for i in range(n):
        if brackets[i] == "(":
            stack.append(i + 1)
        else:
            pair_id = stack.pop()
            nodes[pair_id].pair = i + 1
            nodes[i + 1].pair = pair_id

    for i in range(m):
        if operations[i] == "L":
            p = nodes[p].left
        elif operations[i] == "R":
            p = nodes[p].right
        else:
            pair_id = nodes[p].pair

            left = min(p, pair_id)
            right = max(p, pair_id)

            left_node = nodes[left].left
            right_node = nodes[right].right

            nodes[left_node].right = right_node
            if right_node != n + 1:
                nodes[right_node].left = left_node
                p = right_node
            else:
                p = left_node

    p = nodes[0].right
    result = []
    while p != n + 1:
        result.append(brackets[p - 1])
        p = nodes[p].right

    print("".join(result))

import fractions

def read_data():
    m = int(input())
    h1, a1 = map(int, input().split())
    x1, y1 = map(int, input().split())
    h2, a2 = map(int, input().split())
    x2, y2 = map(int, input().split())
    return m, h1, a1, x1, y1, h2, a2, x2, y2

def solve(m, h1, a1, x1, y1, h2, a2, x2, y2):
    t = 0
    h1s = [-1] * m
    h2s = [-1] * m
    h1s[h1] = 0
    h2s[h2] = 0
    t1 = -1
    t2 = -1
    while h1 != a1 or h2 != a2:
        t += 1
        h1 = (x1 * h1 + y1) % m
        h2 = (x2 * h2 + y2) % m
        if h1s[h1] >= 0 and t1 == -1:
            t1 = h1s[h1]
            s1 = t - t1
            if t2 >= 0:
                break
        else:
            h1s[h1] = t
        if h2s[h2] >= 0 and t2 == -1:
            t2 = h2s[h2]
            s2 = t - t2
            if t1 >= 0:
                break
        else:
            h2s[h2] = t
    if h1 == a1 and h2 == a2:
        return t
    return retrieve(a1, a2, t1, s1, t2, s2, h1s, h2s)

def retrieve(a1, a2, t1, s1, t2, s2, h1s, h2s):
    u1 = h1s[a1]
    u2 = h2s[a2]
    if u1 == -1 or u2 == -1:
        return -1
    if u1 < t1:
        if guess(h2s, u1, t2, s2, a2):
            return u1
        else:
            return -1
    if u2 < t2:
        if guess(h1s, u2, t1, s1, a1):
            return u2
        else:
            return -1
    return find_time(u1, s1, u2, s2)

def guess(hs, u, t, s, a):
    if u <= t:
        return hs[a] == u
    tt = t + (u - t) % s
    return hs[a] == tt

def find_time(u1, s1, u2, s2):
    g = fractions.gcd(s1, s2)
    if abs(u1 - u2) % g:
        return -1
    k1, k2 = extended_euclid(s1, s2, u2-u1, g)
    b = s2 // g
    return (k1 % b) * s1 + u1

def egcd(a, b):
    x, lastx = 0, 1
    y, lasty = 1, 0
    while b:
        q = a // b
        a, b = b, a % b
        x, lastx = lastx - q * x, x
        y, lasty = lasty - q * y, y
    return lastx, lasty

def extended_euclid(a, b, c, g):
    x, y = egcd(a, b)
    return (c // g) * x, (x // g) * y


