        # back
        if i >= mk:
            if processor[i - mk]:
                # front
                if i < (nmk - mk):
                    if processor[i + mk]:
                        counter += 1
                        continue
                # right
                if (i % k) < (k - 1):
                    if processor[i + 1]:
                        if not processor[i - mk + 1]:
                            counter += 1
