                # down
                if (i % mk) < (mk - k):
                    if processor[i + k]:
                        if not processor[i - mk + k]:
                            counter += 1
                            continue
        # left
        if (i % k) > 0:
            if processor[i - 1]:
                # front
                if i < (nmk - mk):
                    if processor[i + mk]:
                        if not processor[i + mk - 1]:
                            counter += 1
                            continue
                # right
                if (i % k) < (k - 1):
