from collections import deque
def main():
    n, m, k = map(int, stdin.readline().split())
    a = [map(int, stdin.readline().split()) for _ in xrange(k)]
    row = [dict() for i in xrange(n + 10)]
    col = [dict() for i in xrange(m + 10)]
    inf = 10010001
    d = [inf] * k
    q = []
    pu = q.append
    for i in xrange(k):
        r, c = a[i]
        row[r][c] = i
        col[c][r] = i
        if r == c == 1:
            d[i] = 0
            pu(i)
    done = [None] * k
    while q:
        v = []
        for x in q:
            r, c = a[x]
            qq = deque()
            qq.append(x)
            done[x] = 1
            while qq:
                y = qq.popleft()
                r, c = a[y]
                for cc in (c-1, c+1):
                    if cc in row[r] and done[row[r][cc]] is None:
                        z = row[r][cc]
                        done[z] = 1
                        qq.append(z)
                for rr in (r-1, r+1):
                    if rr in col[c] and done[col[c][rr]] is None:
                        z = col[c][rr]
                        done[z] = 1
                        qq.append(z)
                d[y] = d[x]
                v.append(y)
        sr = set()
        sc = set()
        del q[:]
        for x in v:
            r, c = a[x]
            for rr in xrange(r - 2, r + 3):
                sr.add(rr)
            for cc in xrange(c - 2, c + 3):
                sc.add(cc)
        for i in sr:
            for j in row[i].viewvalues():
                if d[j] == inf:
                    d[j] = d[x] + 1
                    pu(j)
            row[i] = {}
        for i in sc:
            for j in col[i].viewvalues():
                if d[j] == inf:
                    d[j] = d[x] + 1
                    pu(j)
            col[i] = {}
    ans = inf
    for i in xrange(k):
        r, c = a[i]
        if r == n and c == m:
            if ans > d[i]:
                ans = d[i]
        if r >= n - 1:
            if ans > d[i] + 1:
                ans = d[i] + 1
        if c >= m - 1:
            if ans > d[i] + 1:
                ans = d[i] + 1
    if ans == inf:
        print -1
    else:
        print ans
