from sys import stdin
from bisect import bisect_left, bisect_right

INF = int(1e9)

def find(par, a):
    if par[a] == a:
        return a
    par[a] = find(par, par[a])
    return par[a]

def union(par, rnk, a, b):
    a = find(par,a)
    b = find(par,b)
    if a==b:
        return

    if rnk[a]<rnk[b]:
        par[a] = b
    else:
        par[b] = a
        if rnk[a]==rnk[b]:
            rnk[a] += 1

def solve():
    n, m, k = map(int, stdin.readline().split())
    cnts = list(map(int, stdin.readline().split()))
    for i in range(1,k):
        cnts[i] += cnts[i-1]

    group = list(range(n))
    rnk = [0 for i in range(n)]
    adj = [[INF for j in range(k)] for i in range(k)]
    for i in range(m):
        u, v, x = map(int, stdin.readline().split())
        if x==0:
            union(group, rnk, u-1, v-1)
        tu = bisect_left(cnts, u)
        tv = bisect_left(cnts, v)
        adj[tu][tv] = min(adj[tu][tv], x)
        adj[tv][tu] = min(adj[tv][tu], x)

    p = 0
    for i in range(k):
        cur = group[p]
        while p<cnts[i]:
            if group[p]!=cur:
                print("No")
                return
            p += 1
    print("Yes")

    for p in range(k):
        for i in range(k):
            for j in range(k):
                adj[i][j] = min(adj[i][j], adj[i][p]+adj[p][j])

    for i in range(k):
        adj[i][i] = 0
        for j in range(k):
            if adj[i][j] == INF:
                adj[i][j] = -1

    for i in range(k):
        print(' '.join(map(lambda x: str(x), adj[i])))


solve()

from cmath import rect
import sys
import math
from functools import reduce

class SegmentTree():
    def __init__(self, L, function = lambda x,y: x+y):
        self.function = function
        N = self.size = len(L)
        M = 1 << N.bit_length()
        self.margin = 2*M - N
        self.L = [None for i in range(self.margin)] + L
        for i in range(M-1, 0, -1):
            x, y = self.L[i<<1], self.L[i<<1|1]
            self.L[i] = None if x is None or y is None else function(x, y)
    def modify(self, pos, value):
        p = pos + self.margin
        self.L[p] = value 
        while p > 1:
            x, y = self.L[p], self.L[p^1]
            if p&1: x, y = y, x
            self.L[p>>1] = None if x is None or y is None else self.function(x, y)
            p>>=1
    def query(self, left, right):
        l, r = left + self.margin, right + self.margin
        stack = []
        void = True
        while l < r:
            if l&1:
                if void:
                    result = self.L[l]
                    void = False
                else:
                    result = self.function(result, self.L[l])
                l+=1
            if r&1:
                r-=1
                stack.append(self.L[r])
            l>>=1
            r>>=1
        init = stack.pop() if void else result
        return reduce(self.function, reversed(stack), init)

def degrect(r, phi):
    return rect(r, math.radians(phi))

def vsum(u, v): #u = (x + y*1j, phi)
    return (u[0] + v[0]*degrect(1, u[1]), (u[1] + v[1])%360)

def solve(f):
    n, m = [int(x) for x in f.readline().split()]
    segments = [[1,0] for i in range(n)]
    arm = SegmentTree([(1,0) for i in range(n)], vsum)
    for line in f:
        q, i, a = [int(x) for x in line.split()]
        if q == 1:
            segments[i-1][0] += a
        else:
            segments[i-1][1] -= a
        arm.modify(i-1, (degrect(segments[i-1][0], segments[i-1][1]), segments[i-1][1]))
        query = arm.query(0,n)[0]
        print(query.real, query.imag)

