    done = [[False] * m for _ in xrange(n)]
    par = range(n * m)
    rank = [0] * (n * m)
    def find(x):
        if x == par[x]:
            return x
        else:
            par[x] = find(par[x])
            return par[x]
    def union(x, y):
        x, y = find(x), find(y)
        if x == y: return
        if rank[x] < rank[y]:
            par[y] = x
        else:
            par[x] = y
            if rank[x] == rank[y]:
                rank[x] += 1
    for i in xrange(n):
        for j in xrange(m):
            if a[i][j] == '0': continue
