from sys import stdin
from collections import defaultdict
def emp(l, a):
    cnt = pos = x = 0
    for y in a:
        if y[1]:
            cnt -= 1
        else:
            if not cnt:
                x += y[0] - pos
            cnt += 1
        pos = y[0]
    x += l - pos
    return x
def check(x, b):
    return x ^ b < x
def f(x, b):
    return x - (x ^ b)
def main():
    n, m, k = map(int, stdin.readline().split())
    xcut = defaultdict(list)
    ycut = defaultdict(list)
    for i in xrange(k):
        xb, yb, xe, ye = map(int, stdin.readline().split())
        if xb == xe:
            xcut[xb].extend([(min(yb, ye), 0), (max(yb, ye), 1)])
        else:
            ycut[yb].extend([(min(xb, xe), 0), (max(xb, xe), 1)])
    b = 0
    xb = dict()
    yb = dict()
    for t in xcut.keys():
        xcut[t].sort()
        xb[t] = emp(m, xcut[t])
        b ^= xb[t]
    if (n - 1 - len(xcut)) % 2:
        b ^= m
    for t in ycut.keys():
        ycut[t].sort()
        yb[t] = emp(n, ycut[t])
        b ^= yb[t]
    if (m - 1 - len(ycut)) % 2:
        b ^= n
    if b == 0:
        print "SECOND"
        return
    else:
        print "FIRST"
        if n - 1 - len(xcut) and check(m, b):
