from __future__ import division
from collections import defaultdict
import random
#import numpy as np

def get_cycle(perm, i):
    start = i
    current = i
    res = [i]
    while True:
        new = perm[current]
        perm[current] = -1
        current = new
        if current == start:
            return res
        res.append(current)

def invert_odd_cycle(res, cycle):
    n = len(cycle)
    m = (n - 1) // 2
    for i, e in enumerate(cycle):
        res[e] = cycle[(n + i - m) % n]

def invert_two_even_cycles(res, cycle1, cycle2):
    n = len(cycle1)
    for i in range(n):
        res[cycle1[i]] = cycle2[i]
        res[cycle2[i]] = cycle1[(i+1)%n]

def _sqrtp(perm):
    perm = list(perm)
    res = [None] * len(perm)
    start = 0
    even_cycles = defaultdict(list)
    while True:
        while perm[start] == -1:
            start += 1
            if start >= len(perm):
                for cycles in even_cycles.values():
                    if len(cycles) % 2 == 1:
                        return -1
                    for i in range(len(cycles) // 2):
                        invert_two_even_cycles(res, cycles[2 * i], cycles[2 * i + 1])
                return tuple(res)

        cycle = get_cycle(perm, start)
        if len(cycle) % 2 == 1:
            invert_odd_cycle(res, cycle)
        else:
            even_cycles[len(cycle)].append(cycle)


def sqrtp(perm):
    res = _sqrtp(decp(perm))
    if isinstance(res, tuple):
        return incp(res)
    else:
        return res

def _sqrp(perm):
    res = [None]*len(perm)
    for i,e in enumerate(perm):
        res[i] = perm[perm[i]]
    return tuple(res)

def sqrp(perm):
    return incp(_sqrp(decp(perm)))

def incp(perm):
    return tuple(n + 1 for n in perm)

def decp(perm):
    return tuple(n - 1 for n in perm)

def randp(n):
    res = list(range(n))
    for i in range(1, n):
        #j = np.random.randint(0, i)
        j = random.randint(0, i)
        a = res[i]
        res[i] = res[j]
        res[j] = a
    return incp(res)

