from __future__ import division, print_function

def main():
    n, qs = input_as_list()
    cpn = ceil_power_of_2(n)
    st = array_of(int, n+1)
    switch = array_of(bool, n)

    def update(i, v):
        while i < n:
            st[i] += v
            i |= i+1

    def query(i):
        res = 0
        while i > 0:
            res += st[i-1]
            i &= i-1
        return res

    def lower_bound(s):
        if s <= 0: return -1
        pos = 0
        pw = cpn
        while pw > 0:
            if (pos + pw <= n) and (st[pos + pw-1] < s):
                pos += pw
                s -= st[pos-1]
            pw //= 2
        return pos

    def insert(i):
        update(i, +1)

    def remove(i):
        update(i, -1)

    def find_by_order(i):
        return lower_bound(i)

    def order_of(i):
        return query(i)

    def lr(i):
        o = order_of(i)
        l = find_by_order(o)
        r = find_by_order(o+1)
        return l, r

    ar = input_as_list()
    s1 = [0]
    for x in ar:
        v = s1[-1]+1
        v = mulmod(v, 100)
        v = divmod(v, x)
        s1.append(v)
    s2 = [1]
    for x in ar:
        v = s2[-1]
        v = mulmod(v, 100)
        v = divmod(v, x)
        s2.append(v)

    def f(l, r):
        if r <= l:
            return 0
        a = s1[r]
        b = mulmod(s1[l], s2[r])
        b = divmod(b, s2[l])
        return (a-b)%MOD

    insert(0)
    insert(n)
    ans = s1[-1]
    for _ in range(qs):
        q = int(input())-1
        if switch[q]:
            remove(q)
            l, r = lr(q)
            ans = (ans + f(l, r)) % MOD
            ans = (ans - f(l, q)) % MOD
            ans = (ans - f(q, r)) % MOD
        else:
            l, r = lr(q)
            ans = (ans - f(l, r)) % MOD
            ans = (ans + f(l, q)) % MOD
            ans = (ans + f(q, r)) % MOD
            insert(q)
        switch[q] ^= True
        print(ans)


