mask=(1<<17)-1
def dijkstra():
  hq=[]
  for i in range(n):
    if dist[i]!=inf:
      heappush(hq,(dist[i]<<17)+i)
  seen=[0]*n
  while hq:
    x=heappop(hq)
    w,v=x>>17,x&mask
    if dist[v]<w:
      continue
    seen[v]=True
    for to,cost in edge[v]:
      if seen[to]==False and dist[v]+cost<dist[to]:
        dist[to]=dist[v]+cost
        heappush(hq,(dist[to]<<17)+to)

from collections import deque

class ConvexHullTrick():
  # 追加する直線の傾きが単調
  # 計算する x 座標が単調
  # O(N+Q)

  def __init__(self):
    self.deq=deque()

  def check(self,f1,f2,f3):
    return (f2[0]-f1[0])*(f3[1]-f2[1])>=(f2[1]-f1[1])*(f3[0]-f2[0])

  def f(self,f1,x):
    return f1[0]*x+f1[1]

  # add f_i(x)=a*x+b
  def add_line(self,a,b):
    f1=(a,b)
    while len(self.deq)>=2 and self.check(self.deq[-2],self.deq[-1],f1):
      self.deq.pop()
    self.deq.append(f1)

  # min f_i(x)
  def query(self,x):
    while len(self.deq)>=2 and self.f(self.deq[0],x)>=self.f(self.deq[1],x):
      self.deq.popleft()
    return self.f(self.deq[0],x)


