def solve(n,k,arr):
    t = k
    bits = [0]*31
    for x in arr:
        num = '{:031b}'.format(x)
        for i in range(len(num)):
            if num[i] == "0":
                bits[len(num)-i-1] += 1
    ans = 0
    for i in range(len(bits)-1,-1,-1):
        if k >= bits[i]:
            k -= bits[i]
            ans += pow(2,i)

    return ans





