            steps = 2*((m-1) + (n-m))
            ans.append(steps)
        if (m+n)% 2 != 0:
            steps = 2*((m-1) + (n-m)) - 1
            ans.append(steps)
    if (n==2 and m==1) or (m==2 and n==1):
        steps = 1
        ans.append(steps)
