import sys
raw_input = iter(sys.stdin.read().splitlines()).next

def iter_dfs(adj):
    L, R, D = [[1]*(len(adj)) for _ in xrange(3)]
    cnt = -1
    stk = [(1, ROOT)]
    while stk:
        step, i = stk.pop()
        if step == 1:
            stk.append((2, i))
            cnt += 1
            L[i] = cnt
            for j in reversed(adj[i]):
                D[j] = D[i]+1
                stk.append((1, j))
        elif step == 2:
            R[i] = cnt
    return L, R, D

def iter_dfs2(adj, up, D):
    dp, dp2 = [[0]*(len(adj)) for _ in xrange(2)]
    stk = [(1, ROOT)]
    while stk:
        step, i = stk.pop()
        if step == 1:
            stk.append((2, i))
            for j in reversed(adj[i]):
                stk.append((1, j))
        elif step == 2:
            for j in adj[i]:
                if not dp[j]:
                    if not dp[i]:
                        dp2[i] = max(dp2[i], dp2[j], up[j])
                    continue
                dp2[i] = max(dp2[j], up[j]) if not dp[i] else 0
                dp[i] += dp[j]
            if dp2[i] == D[i]:
                dp2[i] = 0
                dp[i] += 1
    return dp

def solution():
    n, m = map(int, raw_input().strip().split())
    par = map(int, raw_input().strip().split())
    adj = [[] for _ in xrange(n)]
    for i, p in enumerate(par, 1):
        adj[p-1].append(i)
    L, R, D = iter_dfs(adj)
    up, cross = [0]*n, []
    for _ in xrange(m):
        x, y = map(int, raw_input().strip().split())
        x, y = x-1, y-1
        if L[x] > L[y]:
            x, y = y, x
        if R[y] <= R[x]:
            if D[y] == D[x]+1:
                return -1
            up[y] = max(up[y], D[x]+1)
        else:
            cross.append((x, y))
    dp = iter_dfs2(adj, up, D)
    return dp[ROOT]+ any(dp[x]+dp[y] == dp[ROOT] for x, y in cross)

ROOT = 0
print '%s' % solution()

