def process(n, G):
    n = min(n, 1000)
    M = [[0 for j in range(n+1)] for i in range(n+1)]
    for u, v in G:
        if max(u, v) <= n:
            M[u][v] = 1
            M[v][u] = 1
    all_connect = []
    no_connect = []
    if M[1][2] == 1:
        all_connect.append([1, 2])
    else:
        no_connect.append([1, 2])
    for i in range(3, n+1):
        new_all_connect = []
        new_no_connect = []
        for i2 in range(1, i):
            if M[i][i2]==1:
                new_all_connect.append([i2, i])
            else:
                new_no_connect.append([i2, i])
        for x in all_connect:
            new_all_connect.append(x)
            works = True
            for y in x:
                if M[i][y]==0:
                    works = False
                    break 
            if works:
                if len(x+[i])==5:
                    return x+[i]
                new_all_connect.append(x+[i])
        for x in no_connect:
            new_no_connect.append(x)
            works = True
            for y in x:
                if M[i][y]==1:
                    works = False
                    break 
            if works:
                if len(x+[i])==5:
                    return x+[i]
                new_no_connect.append(x+[i])
        all_connect = new_all_connect
        no_connect = new_no_connect
    return [-1]

