def unstable_string(input_str):
    if len(input_str) == 1:
        return 1
    i = 0
    j = 1
    res = 0
    lastj = 0
    last_value = "0/1"
    while i < len(input_str) and j < len(input_str):
        ifok, last_value = judge_ok(input_str[j-1 : j+1], last_value)
        if ifok:
            j = j + 1
        else:
            res += (j - i) * (j - i + 1) // 2
            if lastj > i:
                res -= (lastj - i) * (lastj - i + 1) // 2
            lastj = j
            i = j
            while i >= 0 and input_str[i-1] == '?':
                i -= 1
                last_value = "0/1"
            j = i + 1

    res += (j - i) * (j - i + 1) // 2
    if lastj > i:
        res -= (lastj - i) * (lastj - i +1) // 2
    return res


def judge_ok(substr, last_value):
    if substr == "10" or substr == "01" or (substr == "??" and last_value == "0/1"):
        return True, last_value
    if (substr == "?1" and last_value != "1") or (substr == "?0" and last_value != "0"):
        return True, last_value

    if substr == "??" and last_value == "0":
        return True, "1"
    if substr == "??" and last_value == "1":
        return True, "0"

    if substr == "1?":
        return True, "0"
    if substr == "0?":
        return True, "1"
    return False, last_value


def unstable_string_dp(input_str):
    """
        动态规划做法
    """
    ans = 0
    n = len(input_str)
    dp = [[0, 0] for i in range(n)]
    if input_str[0] == '0':
        dp[0][0] = 1
        dp[0][1] = 0
    elif input_str[0] == '1':
        dp[0][0] = 0
        dp[0][1] = 1
    else:
        dp[0][0] = 1
        dp[0][1] = 1

    ans += max(dp[0][1], dp[0][0])

    for i in range(1, n):
        if input_str[i] == '0':
            dp[i][1] = 0
            dp[i][0] = dp[i - 1][1] + 1
        elif input_str[i] == '1':
            dp[i][0] = 0
            dp[i][1] = dp[i - 1][0] + 1
        else:
            dp[i][0] = dp[i - 1][1] + 1
            dp[i][1] = dp[i - 1][0] + 1

        ans += max(dp[i][1], dp[i][0])

    return ans



