import os
import sys
from io import BytesIO, IOBase

def main():
    n,m = map(int,input().split())
    MOD = 998244353
    adjList = []
    dist = []
    ans = []
    for _ in range(n):
        adjList.append([])
    for _ in range(m):
        a,b = map(int,input().split())
        adjList[a - 1].append(b - 1)
        adjList[b - 1].append(a - 1)
    for i in range(n):
        curDist = [-1] * n
        curDist[i] = 0
        bfsQueue = [i]
        bfsIndex = 0
        while len(bfsQueue) > bfsIndex:
            c = bfsQueue[bfsIndex]
            bfsIndex += 1
            for elem in adjList[c]:
                if curDist[elem] == -1:
                    curDist[elem] = curDist[c] + 1
                    bfsQueue.append(elem)
        dist.append(curDist)
    for _ in range(n):
        ans.append([0] * n)
    for i in range(n):
        for j in range(i, n):
            # Find shortest path between i and j
            isCovered = [False] * n
            isCovered[i] = True
            isCovered[j] = True
            jCpy = j
            flag = True
            while jCpy != i:
                cnt = 0
                cntIndex = -1
                for elem in adjList[jCpy]:
                    if dist[i][elem] == dist[i][jCpy] - 1:
                        cnt += 1
                        cntIndex = elem
                if cnt >= 2:
                    flag = False
                    break
                else:
                    isCovered[cntIndex] = True
                    jCpy = cntIndex
            if not flag:
                ans[i][j] = 0
                ans[j][i] = 0
            else:
                curAns = 1
                for k in range(n):
                    if isCovered[k]:
                        continue
                    cnt = 0
                    for elem in adjList[k]:
                        if dist[i][elem] == dist[i][k] - 1 and dist[j][elem] == dist[j][k] - 1:
                            cnt += 1
                    curAns *= cnt
                    curAns %= MOD
                ans[i][j] = curAns
                ans[j][i] = curAns
    for elem in ans:
        print(" ".join(map(str,elem)))



