            for qq in range(30):
                i = p
                while i == p or i == q:
                    i = idx2.pop()
                if query(i, p) % mx:
                    p = q
                    break
            break
    a[p] = mx
    mx2 = (mx, p)
    for i in range(n):
        if i != p:
            a[i] = query(i, p) // mx
            if a[i] * a[i] <= 220000:
                a[i] = -1
            else:
                mp = max(prime_factors(a[i]))
                if mp != a[i]: continue
                if mp > mx2[0]:
                    mx2 = (mp, i)
    for i in range(n):
        if a[i] == -1:
            a[i] = query(i, mx2[1]) // mx2[0]

    print(*['!'] + a, flush=True)
    continue

