def  GCD(divisor,num):
    if num == 0:
        return divisor
    else:
        return GCD(num , divisor % num)

def solve(array):
    even_divisor = 0
    odd_divisor = 0
    for index in range (0 , len(array)):
        if index % 2 == 0 :
            even_divisor = GCD(even_divisor , array[index])
        else :
            odd_divisor = GCD(odd_divisor , array[index])

    ok = True
    index = 0
    while index < len(array) :
        if array [index] % odd_divisor == 0 :
            ok = False
            break;
        index += 2
    if ok :
        return odd_divisor

    ok = True
    index = 1
    while index < len(array):
        if array[index] % even_divisor == 0:
            ok = False
            break;
        index += 2

    if ok:
        return even_divisor
    return 0

