def is_prime(n):
    if n == 0 or n == 1:
        return False
    d = 2
    while d * d <= n:
        if n % d == 0:
            return False
        d += 1
    return True


def div_up(n, k):
    if n % k == 0:
        return n // k
    else:
        return n // k + 1


def num_len(n, base):
    if n == 0:
        return 1
    res = 0
    while n:
        res += 1
        n //= 10
    return res


def dfs_sample(graph, cl, p, v):
    cl[v] = 1
    for to in graph[v]:
        if cl[to] == 1 and p[v] != to:
            # yay, cycle
            pass
        elif cl[to] == 0:
            p[to] = v
            dfs_sample(graph, cl, p, to)
    cl[v] = 2


def down(a):
    for i in range(1, len(a)):
        if a[i] > a[i - 1]:
            return False
    return True


def up(a):
    for i in range(1, len(a)):
        if a[i] < a[i - 1]:
            return False
    return True


def code(c):
    return ord(c) - 32


def _hash_(s):
    res, p = 0, 1
    for i in range(len(s)):
        res += (code(s[i]) * p)
        res %= MOD
        p *= P
        p %= MOD
    return res % MOD


def remove_edge(v, u, graph):
    graph[v].remove(u)
    graph[u].remove(v)


def all_eq(a):
    for i in range(1, len(a)):
        if a[i] != a[i - 1]:
            return False
    return True


def ok(s):
    for i in range(len(s)):
        for j in range(i, len(s)):
            if s.count(s[i:j+1]) % 2 == 0:
                return False
    return True


