        s.reverse()
        s = ''.join(s)
        return s
    def __add__(self, other):
        A = [0 for i in range(len(self.a))]
        carry = 0
        for i in range(len(self.a)):
            S = self.a[i]+other.a[i]+carry
            if(S <= 25):
                A[i] = S
                carry = 0
            else:
                A[i] = S%26
                carry = 1
        N = base26('')
        N.a = A
        return N

    def div2(self):
        carry = 0
        n = len(self.a)
        for i in range(n-1, -1, -1):
            K = self.a[i]+carry*26
            if(K%2 == 0):
                carry = 0
                self.a[i] = K/2
            else:
                carry = 1
                self.a[i] = K/2



