class dsu:

    def __init__(self , n):

        self.p = [0]*(n)
        self.rank = [0]*(n)

        self.mb , self.mr = [] , []
        for i in range(n):
            self.p[i] = i

            if(color[i] == 1):
                self.mb.append([right[i] , i])
                self.mr.append([-1 , -1])
            else:
                self.mr.append([right[i] , i])
                self.mb.append([-1 , -1])

    def find(self , node):
        if(self.p[node] == node):return node

        self.p[node] = self.find(self.p[node])
        return self.p[node]

    def union(self , u , v):
        u , v = self.find(u) , self.find(v)

        if(self.rank[u] == self.rank[v]):
            self.p[v] = u
            self.rank[u] += 1

            if(self.mb[u][0] < self.mb[v][0]):
                self.mb[u] = self.mb[v][:]

            if(self.mr[u][0] < self.mr[v][0]):
                self.mr[u]=  self.mr[v][:]

        elif(self.rank[u] > self.rank[v]):
            self.p[v] = u

            if(self.mb[u][0] < self.mb[v][0]):
                self.mb[u] = self.mb[v][:]

            if(self.mr[u][0] < self.mr[v][0]):
                self.mr[u]=  self.mr[v][:]

        else:
            self.p[u] = v

            if(self.mb[v][0] < self.mb[u][0]):
                self.mb[v] = self.mb[u][:]

            if(self.mr[v][0] < self.mr[u][0]):
                self.mr[v]=  self.mr[u][:]

    def best_red(self , u):

        u = self.find(u)
        return self.mr[u][1]

    def best_blue(self , u):

        u = self.find(u)
        return self.mb[u][1]


def answer():

    s.sort()

    d = dsu(n)
    blue , red = set() , set()
    for i in range(len(s)):
        x , what , colour , node = s[i]

        if(what == 1):

            if(colour == 0):

                if(len(blue) == 0):
                    red.add(d.best_red(node))
                else:

                    for x in blue:
                        d.union(x , node)

                    blue.clear()
                    blue.add(d.best_blue(node))
                    red.add(d.best_red(node))
            else:

                if(len(red) == 0):
                    blue.add(d.best_blue(node))
                else:

                    for x in red:
                        d.union(x , node)

                    red.clear()
                    blue.add(d.best_blue(node))
                    red.add(d.best_red(node))

        else:

            blue.discard(node)
            red.discard(node)

    ans = set()
    for i in range(n):
        ans.add(d.find(i))

    return len(ans)


