                        temp += 1

                delta.append(temp)

            for v in range(n):
                a[v] += delta[v]

            if max(a) == 0:
                success = True
                break

        if success:
            stdout.write(str(time)+'\n')

        else:
            stack = toposort(out_neighbours)
            for v in stack:
                for w in out_neighbours[v]:
                    a[w] = (a[w]+a[v])%N

            stdout.write(str((time+a[v])%N)+'\n')

