def neigh(i,j):
    res = []
    if i > 0:
        res.append((i-1,j))
    if i < N-1:
        res.append((i+1,j))
    if j > 0:
        res.append((i,j-1))
    if j < M-1:
        res.append((i,j+1))
    return res

