def f(u, v):
    return u * m + v

def g(u):
    return u // m, u % m

def bfs():
    dist = [inf] * l
    q, q0 = [], []
    k, k0 = 0, 0
    for i in range(0, l, m):
        if not ng[i]:
            dist[i] = s[i]
            if not dist[i]:
                q.append(i)
            else:
                q0.append(i)
    parent = [-1] * l
    for d in range(l + 1):
        while len(q) ^ k:
            u = q[k]
            i, j = g(u)
            for di, dj in v2:
                ni, nj = i + di, j + dj
                if not 0 <= ni < n or not 0 <= nj < m:
                    continue
                v = f(ni, nj)
                if ng[v] or dist[v] ^ inf:
                    continue
                dist[v] = d + s[v]
                parent[v] = u
                if not s[v]:
                    q.append(v)
                else:
                    q0.append(v)
            k += 1
        q, q0 = q0, q
        k, k0 = k0, k
    return dist, parent

