def solve(s):
    from collections import Counter
    c = Counter(s)
    a = (c['?'] + c[')'] - c['(']) // 2
    b = c['?'] - a

    q = 0
    l = r = None
    for i, c in enumerate(s):
        if c == '?':
            if q < a:
                l = i
            elif r is None:
                r = i
            q += 1
    if l is None or r is None:
        return 'YES'

    check = 0
    for i, c in enumerate(s):
        if c == '(':
            check += 1
        elif c == ')':
            check -= 1
        elif i < l:
            check += 1
        elif i == l:
            check -= 1
        elif i == r:
            check += 1
        else:
            check -= 1
        if check < 0:
            return 'YES'
    if check != 0:
        return 'YES'
    return 'NO'

