t = list(map(int,input().split()))
def f(num):
    res = 1
    for i in range(1,num+1):
        res *= i
        res %= mod
    return res

ans = 0
mod = 998244353
cnt1 = Counter(s)
cnt2 = Counter(t)
a = f(m)
for v in cnt1.values():
    if v > 1:
        a *= pow(f(v),mod-2,mod)
        a %= mod
d = SortedList(s)
ok = True
ta = 0
for i in range(min(m,n)-1):
