def nexp(i, max):
    exp = ceil(log(i, 2))
    if 2**exp -i < 15 and 2**exp -i + 15 - exp < 15:
        return 2**exp -i + 15 - exp

    else:
        tmp = i
        steps=0
        if i%2 !=0:
                i+=1
                steps+=1

        while i % c != 0:
            if steps > max:
                return max +1
            i*=2
            steps +=1
        return steps

def minsteps(i):
    exp = ceil(log(i, 2))

    if i==0:
        return 0
    else:
        steps = 15

        for j in range(15):
            tmp = j+i
            c =0
            while tmp%2==0:
                tmp /= 2
                c+=1

            steps = min(steps, j+ 15-c)

        return steps

