import sys

def Column2Num( m, idx ):
    return int(m[0][idx] != 0)  | (int(m[1][idx]) << 1) | (int(m[2][idx]) << 2)

def QColumn( m, bits, idx ):
    if bits[idx] == 5:
        if m[0][idx] == m[2][idx]:
            return True
    return False

def GetIntegratedCount( m ):
    ret, curr = [ 0 ], set()
    for c in range( len( m[0] ) ):
        if m[0][c] != 0: curr.add( m[0][c] )
        if m[1][c] != 0: curr.add( m[1][c] )
        if m[2][c] != 0: curr.add( m[2][c] )
        ret.append( len( curr ) )
    ret.append( len( curr ) )
    return ret

def Print( tm ):
    print( '\n', tm[0], '\n', tm[1], '\n', tm[2] )

def PrintIndexed( tm ):
    for i in range( len( tm[0] ) ):
        print(  i+1, ':', tm[0][i], tm[1][i], tm[2][i] )

def next( b, next ):

    b &= next

    if b == 0:
        return b

    if b & 1 or b & 4:
        if next & 2:
            b |= 2

    if b & 2:
        if next & 1:
            b |= 1
        if next & 4:
            b |= 4

    return b

def setCompNumber( b, m, i, compNumber ):
    if b & 1:
        m[0][i] = compNumber
    if b & 2:
        m[1][i] = compNumber
    if b & 4:
        m[2][i] = compNumber


def goLeft( start, compNumber, size, m, bits, fullColumn ):
    b = bits[start]
    fc = start

    for i in range( start - 1, -1, -1 ):

        b = next( b, bits[i] ) 

        if b == 7:
            fc = i
            break

        if b == 0:
            break

        setCompNumber( b, m, i, compNumber )

        if b == 5:
            fullColumn[ i ] = fc


def goRight( start, compNumber, size, m, bits, fullColumn ):

    b = bits[start]

    for i in range( start, size ):

        b = next( b, bits[i] ) 

        if b == 7:
            fc = i

        if b == 0:
            break

        setCompNumber( b, m, i, compNumber )

        if b == 5:
            fullColumn[ i ] = fc

def goRight12( b, start, compNumber, size, m, bits ):

    for i in range( start, size ):

        b = next( b, bits[i] ) 
        if b == 0:
            break

        setCompNumber( b, m, i, compNumber )


def get3Components( compNumber, size, m, bits, leftFullColumn, rightFullColumn ):
    for i in range( size ):
        if bits[i] == 7:
            if m[ 0 ][ i  ] == 1:
                compNumber += 1
                goRight( i, compNumber, size, m, bits, leftFullColumn )
            goLeft ( i, compNumber, size, m, bits, rightFullColumn )
    return compNumber

def get12Components( compNumber, size, m, bits ):
    for i in range( size ):
        if m[ 0 ][ i  ] == 1:
            compNumber += 1
            goRight12( 1, i, compNumber, size, m, bits )
        if m[ 1 ][ i  ] == 1:
            compNumber += 1
            goRight12( 2, i, compNumber, size, m, bits )
        if m[ 2 ][ i  ] == 1:
            compNumber += 1
            goRight12( 4, i, compNumber, size, m, bits )

def SolveBB( m, bits, integratedCount, s, e, leftFullColumn, rightFullColumn ):
    #debug = 0
    #print( 'start,end =',s, e )
    #if debug: Print( [ m[0][s-1:e], m[1][s-1:e], m[2][s-1:e] ] )

    sol1 = 0
    if s-1 == 0:
        sol1 = integratedCount[e]
    else:
        startCnt = 1
        if bits[s-1] == 0:
            startCnt = 0
        elif bits[s-1] == 5:
            if m[0][s-1] != m[2][s-1]:
                startCnt = 2

        sol1 = startCnt + integratedCount[e] - integratedCount[s]

    sQ = QColumn( m, bits, s - 1)
    eQ = QColumn( m, bits, e - 1)


    if sQ and eQ:
       if m[0][s-1] == m[2][s-1]:
           if rightFullColumn[s-1] == rightFullColumn[e-1]:
                sol1 += 1
                return sol1 
           elif leftFullColumn[s-1] == leftFullColumn[e-1]:
                sol1 += 1
                return sol1 

    if sQ:
       if rightFullColumn[s-1] != -1:
            if rightFullColumn[s-1] > e-1:
                sol1 += 1
       else:
            sol1 += 1
    if eQ:
        if leftFullColumn[e-1] != -1:
            if leftFullColumn[e-1] < s-1:
                sol1 += 1
        else:
            sol1 += 1

    return sol1

def mainBB():
    debug = 0
    input = sys.stdin
    if len( sys.argv ) >= 2:
        input = open( sys.argv[1], 'r' )

    size = int( input.readline() )
    m = []
    for i in range( 3 ):
        m.append( [ int( t ) for t in list( input.readline().strip() ) ] )
    bits = [ Column2Num( m, i ) for i in range( size ) ]    

    leftFullColumn = [ -1 for i in range( size ) ]
    rightFullColumn = list(  leftFullColumn )

    compNumber = get3Components( 1, size, m, bits, leftFullColumn, rightFullColumn )
    get12Components( compNumber, size, m, bits )
    integratedCount = GetIntegratedCount( m )

    if debug: PrintIndexed( m )
    if debug: Print( m )
    if debug: print( integratedCount )
    if debug: print( leftFullColumn )
    if debug: print( rightFullColumn )

    n = int( input.readline() )
    for i in range( n ):
        ln = input.readline().strip().split()
        s = int( ln[0] )
        e = int( ln[1] )
        if debug: print( s, e, m )

        print( SolveBB( m, bits, integratedCount, s, e, leftFullColumn, rightFullColumn ) )

if __name__ == "__main__":
    mainBB()

import sys
from os import path

def solve(word):
  # handel string input from codeforces
  hieghts=word.split(" ")
  trees = [int(i) for i in hieghts]
  Max = max(trees)
  Sum = 0
  c1  = 0
  #count number of even and odd days needed for all trees
  for i in trees:
    dist = Max - i
    if(dist%2 == 1):
      Sum += (dist//2)
      c1+=1
    else:
      Sum += (dist//2)
  # if number of odd greater than number of even you just need twice odd number
  # but you don't need the last day because it's even 
  if c1 > Sum+1:
    ans=c1+c1-1
  #if the number of even greater than odd try to find min days that gives you
  #even growth by using both even and odd days
  elif Sum > c1:
    x= (Sum -c1)*2    #convert number of even days to number of days (multiply by 2)
                      #for every 3 days we have 2 odds and one even as we have 2 evens 
    if x%3==0:
      ans = x//3 *2
    elif x%3==1:
      ans = x//3 *2+1
    else:
      ans = x//3 *2 +2
    ans+=c1*2
  # if the number of even equal to number of odd-
  # -or smaller by one so you need thier sum
  else:
    ans = c1 +Sum
  # repeat the previos steps but with target length equal max+1
  # because min time achived if length equal max or max+1 and get min of the two
  Sum = 0 
  c1  = 0
  for i in trees:
    dist = Max - i +1
    if(dist%2 == 1):
      Sum += (dist//2)
      c1+=1
    else:
      Sum += (dist//2)
  if c1 > Sum+1:
    ans2=c1+c1-1
  elif Sum > c1:
    x= (Sum -c1)*2
    if x%3==0:
      ans2 = x//3 *2
    elif x%3==1:
      ans2 = x//3 *2+1
    else:
      ans2 = x//3 *2 +2
    ans2+=c1*2
  else:
    ans2 = c1 +Sum
  return min(ans , ans2) 
