def solveonecolor(array):

    m = len(array)
    if m==0:
        return 0
    elif m==1:
        return 1
    else:
        maxi = 1
        for i in range(m-1):
            if (array[i+1]-array[i])%2==1:
                maxi+=1

    return maxi


def solve(n, array):
    allans = []
    subarrays = [[] for _ in range(n)]
    for i in range(n):
        color = array[i]-1
        subarrays[color].append(i)

    for color in range(n):
        allans.append(solveonecolor(subarrays[color]))
    print(" ".join(str(i) for i in allans))


