mxn=10**9 + 7

def modI(a, m):

    m0=m
    y=0
    x=1;
    if(m==1): return 0;
    while(a>1):

        q=a//m;
        t=m;
        m=a%m;
        a=t;
        t=y;
        y=x-q*y;
        x=t;

    if(x<0):x+=m0;
    return x;

def fastfrac(a,b,M):
    numb = modI(b,M)
    return ((a%M)*(numb%M))%M


