from functools import cache

def par(x):
    cnt = 0
    while x:
        cnt += 1
        x &= x - 1
    return cnt & 1

@cache
def solve(n, m):
    if m == 0:
        return 0
    if m & 1:
        return solve(n, m - 1) + int(par(m - 1) != par(n + m - 1))
    if n & 1:
        return m - solve(n // 2, m // 2) - solve(n // 2 + 1, m // 2)
    else:
        return 2 * solve(n // 2, m // 2)

