def memoize(f):
  st = {}

  def _mk_r():
    def r(*args):
      _k = args
      if _k in st:
        return st[_k]
      c = f(*args)
      st[_k] = c
      # print(f'{key}{_k} -> {c}')
      return c

    return r

  return _mk_r()
