M=(10**5) 
fac=[1]*M
ninv=[1]*M
finv=[1]*M
for i in range(2,M):
  fac[i]=fac[i-1]*i%mod
  ninv[i]=(-(mod//i)*ninv[mod%i])%mod
  finv[i]=finv[i-1]*ninv[i]%mod

def binom(n,k):
  if n<0 or k<0:
    return 0
  if k>n:
    return 0
  return (fac[n]*finv[k]%mod)*finv[n-k]%mod

def conv(a,b):
  na=len(a)
  nb=len(b)
  c=[0]*(na+nb-1)
  for i in range(na):
    for j in range(nb):
      c[i+j]=(c[i+j]+a[i]*b[j])%mod
  return c

