    edge[b].append(a)
    edges.append((a,b))

  ans=0

  for i in range(n):
    dp=[[1] for i in range(n)]
    for j in edge[i]:
      cnt=[0]*n
      todo=[(1,j,i)]
      while todo:
        d,v,p=todo.pop()
        cnt[d]+=1
        for u in edge[v]:
          if u!=p:
            todo.append((d+1,u,v))

      for j in range(n):
        if cnt[j]!=0:
          s=cnt[j]
          dp[j]=conv(dp[j],[1,s])

    for j in range(n):
      if len(dp[j])>=k+1:
        ans+=dp[j][k]
        ans%=mod

  for v1,v2 in edges:
