from collections import defaultdict, deque

def memoize(function):
    cache = {}
    def decorated_function(*args):
        try:
            return cache[args]
        except KeyError:
            val = function(*args)
            cache[args] = val
            return val
    return decorated_function

@memoize
def can(limit, k):
    G = defaultdict(list)

    D = [0] * n

    vcount = 0
    for s, e in E:
        if A[s] <= limit and A[e] <= limit:
            G[s].append(e)
            D[e] += 1
            if D[e] == 1:
                vcount += 1
        else:
            break

    Q = deque()
    for i, a in As:
        if a <= limit:
            if D[i] == 0:
                Q.append((i, k - 1))
                vcount += 1
        else:
            break

    while Q:
        s, d = Q.popleft()
        if d == 0:
            return True

        vcount -= 1

        if s in G:
            for e in G[s]:
                D[e] -= 1
                if D[e] == 0:
                    Q.append((e, d - 1))


    return vcount >= 2



