from collections import deque

def parity(n):
    parity = 0
    while n:
        parity = 1-parity
        n = n & (n-1)
    return parity

t = int(stdin.readline())

for _ in range(t):
    n, m = [int(x) for x in stdin.readline().split()]
    edges = []
    fake_edges = {i: [] for i in range(n)}
    possible = True

    for bar in range(n-1):
        x, y, v = [int(z) for z in stdin.readline().split()]
        x -= 1
        y -= 1
        edges.append((x,y,v))
        if v >= 0:
            p = parity(v)
            fake_edges[x].append((y,p))
            fake_edges[y].append((x,p))

    for bar in range(m):
        x, y, v = [int(z) for z in stdin.readline().split()]
        x -= 1
        y -= 1
        fake_edges[x].append((y,v))
        fake_edges[y].append((x,v))

    r_values = [-1]*n
    touched = [False]*n

    for i in range(n):
        if not possible:
            break
        if not touched[i]:
            queue = deque()
            queue.append(i)
            r_values[i] = 0
            touched[i] = True

            while len(queue) > 0:
                if not possible:
                    break
                v = queue.popleft()
                for w,p in fake_edges[v]:
                    if r_values[w] == -1:
                        r_values[w] = r_values[v] ^ p
                        touched[w] = True
                        queue.append(w)
                    else:
                        if r_values[w] != r_values[v] ^ p:
                            possible = False
                            break

    if possible:
        stdout.write('YES\n')
        for v, w, new_temp in edges:
            if new_temp == -1:
                new_temp = r_values[v] ^ r_values[w]
            stdout.write('{} {} {}\n'.format(v+1,w+1,new_temp))

    else:
        stdout.write('NO\n')

