def mexp(size,power):
    A=[]
    for i in range(size):
        A.append([int(j<=(i//2)*2) for j in range(size)])
    powers={1: A}
    p=1
    while p*2<=power:
        powers[p*2]=mmmult(powers[p],powers[p])
        p*=2
    A=powers[p]
    power-=p
    while power>0:
        p=p//2
        if p<=power:
            A=mmmult(A,powers[p])
            power-=p
    return A                

def mvmult(A,V):
    res=[]
    for i in range(len(A)):
        res.append(sum(a*v for a,v in zip(A[i],V)) % 998244353 )
