def mmmult(A,B):
    res=[]
    for i in range(len(A)):
        res.append([sum(a*B[j][k] for j,a in enumerate(A[i])) for k in range(len(B[0]))])
    return res

def get_rep(corners):
    corners[0]-=1
    corners[-1]+=1
    bps=sorted(list(set(corners)))
    m=len(bps)
    X=[1]
    active=[1]
    for i in range(1,m):
        x,y=bps[i-1],bps[i]
        d=y-x
        A=mexp(len(active),d)
        X=mvmult(A,X)
        #debug(active,X)
        #debug(A)     
        if i<m-1:
            for j,c in enumerate(corners):
                if c==y:
                    if j%2: # top: j and j+1 in active
                        idx=active.index(j)
                        X[idx+2]+=X[idx]
                        active.pop(idx)
                        active.pop(idx)
                        X.pop(idx)
                        X.pop(idx)
                    else: # bottom
                        active+=[j,j+1]
                        active.sort()
                        idx=active.index(j)
                        X=X[:idx]+[0,X[idx-1]]+X[idx:]
        else:
            return X[0]

