                node[v] = x[0] + t[0]
                if p != -1:
                    edge[ind[(v, p)]] = t[0]
            t[0] += 1
            for i in graph[v]:
                if i != p:
                    dfs(i, v, lev + 1)

        dfs(0, -1, 0)
