def dijkstra():
    dist = [inf] * l
    visit = [0] * l
    h = []
    for i in range(n):
        si = s[i]
        for j in range(m):
            if si[j] == 46:
                u = f(i, j)
                dist[u] = 0
                heapq.heappush(h, (dist[u], u))
    while h:
        d, u = heapq.heappop(h)
        if dist[u] < d:
            continue
        visit[u] = 1
        for v in G[u]:
            c = q if u // m == v // m or not (u - v) % m else p
            nd = dist[u] + c
            if not visit[v] and nd < dist[v]:
                dist[v] = nd
                heapq.heappush(h, (dist[v], v))
    return dist

