def gcd(a, b):
    if a > b:
        a, b = b, a
    if b % a==0:
        return a
    return gcd(b % a, a)

def process(A):
    n = len(A)
    if n==1:
        sys.stdout.write('0\n')
        return
    d = {}
    check = [None for i in range(72**2)]
    for i in range(72):
        i2 = i*(i-1)//2
        check[i2] = i
    for i in range(n):
        for j in range(i):
            num = A[i]-A[j]
            den = (i-j)
            if num==0:
                den = 1
                sign = 1
                g = 1
                start = A[i]
            else:
                if num > 0:
                    sign = 1
                else:
                    sign = -1
                start = den*A[i]-num*i
                g = gcd(abs(num), den)
                num = num//g
                den = den//g
                start = den*A[i]-num*i
           # print(i, j, A[j], A[i], start, num, den)
            if (start, num, den) not in d:
                d[(start, num, den)] = 0
            d[(start, num, den)]+=1
    answer = 0
    for x in d:
        if check[d[x]] is not None:
            answer =  max(answer, check[d[x]])
    sys.stdout.write(f'{n-answer}\n')


