                        last -= c
                    else:
                        flip_bit(row[0], k)
                last %= 3
                if last == 1:
                    flip_bit(row[0], m)
                elif last == 2:
                    flip_bit(row[0], m)
                    flip_bit(row[1], m)

                ans.add(tuple(tuple(x) for x in row))

    mat1, mat2 = [], []
    for x, y in ans:
        mat1 += [list(x)]
        mat2 += [list(y)]

    ans = Gauss(mat1, mat2, len(mat1), m)

    if ans[0] == 0:
        out = [-1]
    else:
        out = []
        for i in range(m):
            if colors[i] != -1:
                out += [colors[i]]
            elif ans[1][i] == 0:
                out += [3]
            else:
                out += [ans[1][i]]

    print(" ".join(str(x) for x in out))

