import sys

def stringComparator(a, b):
    n = len(a)
    m = len(b)
    size = 0

    for i in range(1, min(n,m) + 1):
        for j in range(0, n - i + 1):
            for k in range(0, m - i + 1):
                if (a[j: j + i] == b[k: k + i]):
                    size = max(size, i)

    #print("final size:",size)                
    return((len(a) + len(b)) - (size * 2))


