def toposort(graph):
    res, found = [], [0] * len(graph)
    stack = list(range(len(graph)))
    while stack:
        node = stack.pop()
        if node < 0:
            res.append(~node)
        elif not found[node]:
            found[node] = 1
            stack.append(~node)
            stack += graph[node]

    # cycle check
    for node in res:
        if any(found[nei] for nei in graph[node]):
            return None
        found[node] = 0

    return res[::-1]


def kahn(graph):
    n = len(graph)

    indeg, idx = [0] * n, [0] * n
    for i in range(n):
        for e in graph[i]:
            indeg[e] += 1

    q, res = [], []
    for i in range(n):
        if indeg[i] == 0:
            q.append(i)  # heappush(q, -i)

    nr = 0
    while q:
        res.append(q.pop())  # res.append(-heappop(q))
        idx[res[-1]], nr = nr, nr + 1
        for e in graph[res[-1]]:
            indeg[e] -= 1
            if indeg[e] == 0:
                q.append(e)  # heappush(q, -e)

    return res, idx, nr == n


def make_string(s):
    k = len(s)
    answer = 0
    for i in range(k):
        if s[i]=='_':
            entry = 26
        else:
            entry = ord(s[i])-ord('a')
        answer = 27*answer+entry
    return answer

def make_strings(s):
    k = len(s)
    answer = [0]
    for i in range(k):
        answer2 = []
        for x in answer:
            for y in [26, ord(s[i])-ord('a')]:
                answer2.append(27*x+y)
        answer = answer2
    return answer


def process(P, S):
    n = len(P)
    m = len(S)
    k = len(P[0])
    d = [[None, None] for i in range(27**k)]
    for i in range(n):
        x = make_string(P[i])
        d[x][0] = i+1
    graph = [[] for i in range(n)]
    for i in range(m):
        s1, x1 = S[i]
        works = False
        for s2 in make_strings(s1):
            if d[s2][0] is not None:
                y = d[s2][0]
                if y != x1:
                    graph[x1-1].append(y-1)
                if y==x1:
                    works = True
        if not works:
            sys.stdout.write('NO\n')
            return
    a, b, c = kahn(graph)
    if not c:
        sys.stdout.write('NO\n')
        return
    answer = [None for i in range(n)]
    for i in range(n):
        answer[b[i]] = i+1
    sys.stdout.write('YES\n')
    answer = ' '.join(map(str, answer))
    sys.stdout.write(f'{answer}\n')

