import string

def is_abc(S):
    abc = list(string.ascii_lowercase)
    del abc[0]

    if S == 'a':
        return True

    if S == '':
        return True


    if len(set(S)) == len(S) and 'a' in S:
        a = S.index('a')
        prev_S = list(reversed(S[:a]))
        post_S = S[a+1:]
        c = len(prev_S) + len(post_S)

        for i in range(c):
            current_S = abc[i]
            prev = prev_S[0] if prev_S else None
            post = post_S[0] if post_S else None

            if current_S == prev:
                del prev_S[0]
            elif current_S == post:
                del post_S[0]
            else:
                return False
        return True
    else:
        return False

