        for j in range(i, MX + 1, i):
            primeFactors[j].append(i)

    MXH = 18
    nxt = [N for _ in range(MX + 1)]
    dp = [[N for _ in range(MXH + 1)] for __ in range(N + 1)]
    for i in range(N - 1, -1, -1):
        dp[i][0] = dp[i + 1][0]
        for factor in primeFactors[A[i]]:
