    i = 1
    ans=[]
    while i <= sqrt(n):

        if (n % i == 0) :

            # If divisors are equal, print only one
            if (n / i == i) :
                ans.append(i)
            else :
                # Otherwise print both

                ans.append(i)
                ans.append(int(n/i))
        i = i + 1
    return ans

