class TopSort_Tree:
    def __init__(self, n) -> None:
        self.n = n
        self.graph = defaultdict(set)
        self.parent = [n + 1 for _ in range(self.n)]

    def add_edge(self, a, b):
        self.graph[a].add(b)
        self.graph[b].add(a)

    def sort(self, root):
        graphlist = []
        q = deque()
        q.append((root, -1))
        while q:
            cur, fa = q.popleft()
            graphlist.append(cur)
            for e in self.graph[cur]:
                if e == fa:
                    continue
                else:
                    self.parent[e] = cur
                    q.append((e, cur))
        return graphlist[::-1]

def solve():
    n, k = MI()
    gl = TopSort_Tree(n)
    xorsum = [[0 for _ in range(k << 1)] for _ in range(n)]
    win = [0 for _ in range(n)]

    for _ in range(n - 1):
        x, y = MI()
        x -= 1
        y -= 1
        gl.add_edge(x, y)
    nums = LII()

    graphlist = gl.sort(0)

    for node in graphlist:
        xorsum[node][0] ^= nums[node]
        if node == 0:
            break
        fa = gl.parent[node]
        for depth in range(k << 1):
            xorsum[fa][depth] ^= xorsum[node][depth - 1]
    #print(xorsum)

    q = deque()
    q.append((0, -1, [0 for _ in range(k << 1)]))

    while q:
        node, fa, prev_xors = q.popleft()
        final_xors = [x ^ y for x, y in zip(prev_xors, xorsum[node])]

        for e in gl.graph[node]:
            if e == fa:
                continue
            send_xors = final_xors[:]
            for i in range(k << 1):
                send_xors[i] ^= xorsum[e][i - 1]
            send_xors = [send_xors[-1]] + send_xors[:-1]
            q.append((e, node, send_xors))

        odd_xors = 0
        for i in range(k, k << 1):
            odd_xors ^= final_xors[i]

        win[node] = 1 if odd_xors else 0

    print(*win)    
