from math import atan2, asin

def dist(a, b):
    return ((a[0]-b[0])**2 + (a[1]-b[1])**2)**0.5

def check(R, p, i, dp):
    left, right = float("-inf"), float("inf")
    for j in range(len(p)):
        if j == i:
            continue
        d = dist(p[i], p[j])
        if R >= d:
            continue
        delta = asin(R/d)
        angle = atan2(p[j][1]-p[i][1], p[j][0]-p[i][0])
        l, r = angle-delta, angle+delta
        if l > right:
            l, r = l-2*PI, r-2*PI
        elif r < left:
            l, r = l+2*PI, r+2*PI
        left, right = max(left, l), min(right, r)
        if left > right:
            return
    for j in range(len(p)):
        if j == i:
            continue
        angle = atan2(p[j][1]-p[i][1], p[j][0]-p[i][0])
        if angle > right:
            angle -= 2*PI
        elif angle < left:
            angle += 2*PI
        if left <= angle <= right:
            dp[i][j] = 1

def solution():
    n, R = list(map(int, input().strip().split()))
    p = [list(map(int, input().strip().split())) for _ in range(n)]
    dp = [[0]*n for _ in range(n)]
    for i in range(n):
        check(R, p, i, dp)
    return sum(dp[i][j] and dp[j][i] for i in range(n) for j in range(i, n))

PI = 2*atan2(1, 0)
