    else:
      S[n][k]=S[n-1][k-1]+k*S[n-1][k]
      S[n][k]%=mod

def fpow(x,k):
  res=1
  if k<0:
    return 0
  while k:
    if k&1:
      res=res*x%mod
    x=x*x%mod
    k>>=1
  return res


def solve():
  N,M,K=map(int,input().split())
  ans=0
  res=fpow(M,N)
  Minv=fpow(M,mod-2)
  for i in range(1,K+1):
    res*=(N-i+1)*((M+1)//2)%mod*Minv%mod
    res%=mod
    ans+=res*S[K][i]%mod
    ans%=mod

  print(ans)

for _ in range(int(input())):
  solve()

import os
