MOD = 998244353


facts = [1]
for i in range(1, 100001):
    facts.append(facts[-1] * i % MOD)


def qpow(x, y):
    ret = 1
    b = x
    while y > 0:
        if y & 1:
            ret = ret * b % MOD
        b = b * b % MOD
        y >>= 1
    return ret


def inv(x):
    return qpow(x, MOD - 2)


def CC(n, m):
    return facts[n] * inv(facts[m]) % MOD * inv(facts[n - m]) % MOD


