from functools import lru_cache
@lru_cache(maxsize=None)
def is_prime(a):
	if a==1:return False
	for i in range(2,int(a**0.5)+1):
		if a%i==0:
			return False
	return True

def cal(B):
	ans = 0
	for i,b in enumerate(B):
		if b==2:
			l,r = i,i
			for j in range(i-1,-1,-1):
				if B[j]==1:
					l=j
				else:
					break
			for j in range(i+1,len(B)):
				if B[j]==1:
					r=j
				else:
					break
			ans += (r-i)+(i-l)+(r-i)*(i-l)
	return ans

