def solve(A):
    if len(A) <= k:
        for a in A:
            check(a)
        return

    B = []
    while A:
        B.append(A[-(k//2):])
        del A[-(k//2):]
    m = len(B)
    for i in range(m):
        j = i + 1
        while j < m:
            for b in B[j]:
                check(b)
            j += 1
            for b in B[i]:
                check(b)
            if j < m:
                for b in B[j]:
                    check(b)
                j += 1
            reset()

