import math
from decimal import *
def sqrt(v):
    a = Decimal(0)
    b = v
    while a != b:
        a = b
        b = (a+v/a)/TWO
    return a
def taylor_acos(v):
    return PI/2 - taylor_asin(v)
def taylor_asin(v):
    curr = v
    vsq = v**2
    ans = v
    coef = Decimal(1.)
    for i in xrange(3, 101, 2):
        curr *= vsq
        coef = coef * (i-2) / (i-1)
        ans += curr * coef / i
    return ans
def acos(v):
    if v <= S:
        return Decimal(taylor_acos(v))
    return Decimal(taylor_asin(sqrt(1-v**2)))
def sector(a, b, c, csq):
    d = Decimal(b**2+csq-a**2)
    e = TWO*Decimal(b)*c
    f = acos(d/e)
    return f*(Decimal(b)**2)
