@bootstrap
def dfs(node):
    visited[node] = True
    ans[node] = 1 if ls[node-1] else -1
    for i in children[node]:
        if not visited[i]:
            parent[i] = node
            tmp = (yield dfs(i))
            if tmp>0:
                ans[node]+=tmp
    ans[node] = max(ans[node], 1 if ls[node-1] else -1)
    yield ans[node]
