    zero_union = set()

    for v in range(n):
        cnt = Counter()
        for src in rev_edges[v]:
            cnt[find(src)] += 1

        for zero_v in zero_union:
            root = find(zero_v)
            if size(root) > cnt[root]:
                unite(root, v)

        zero_union = set(find(v_) for v_ in zero_union) | {find(v)}

    print(len(zero_union)-1)

def getMax(s,i,j,t,k,n):
    res = 0
    count = 0 
    while i<n :
        while j<n and count<k:
            if s[j]!=t:
                count+=1
            j+=1
        while j<n and s[j]==t:
            j+=1
        res = max(res,j-i)
        while i<n and s[i]==t:
            i+=1
        if i<n :
            i+=1
            count-=1
    return res

