def lca(a, b):
    while depth[a] > depth[b]:
        a = parent[a]
    while depth[b] > depth[a]:
        b = parent[b]
    while a != b:
        a = parent[a]
        b = parent[b]
    return a


def parent_path(a, b):
    p = []
    while a != b:
        p.append(str(a))
        a = parent[a]
    p.append(str(b))
    return p


def gett(a, b, u, v):
    if depth[b] > depth[v]:
        a, b, u, v = u, v, a, b
    e = lca(a, u)
    print('YES')
    c1 = parent_path(e, v)
    print(' '.join([str(len(c1))] + c1))
