    visited[i] = True
    depth[i] = depth[parent[i]] + 1
    for ni in adj[i]:
        if parent[i] != ni:
            if not visited[ni]:
                parent[ni] = i
                dfs(ni)
            elif depth[ni] < depth[i]:
                x = i
                while x != ni:
                    if cx[x] and cy[x]:
                        gett(cx[x], cy[x], i, ni)
                    else:
                        cx[x] = i
                        cy[x] = ni
                    x = parent[x]


def dfs2(i):
    visited[i] = True
    q: List[int] = []
    q.append(i)
    while len(q) > 0:
        u = q[-1]
        if qi[u] >= len(adj[u]):
            q.pop()
            continue
        v = adj[u][qi[u]]
        qi[u] += 1
        if parent[u] != v:
            if not visited[v]:
                parent[v] = u
                depth[v] = depth[u] + 1
                visited[v] = True
                q.append(v)
            elif depth[v] < depth[u]:
                x = u
                while x != v:
                    if cx[x] and cy[x]:
                        gett(cx[x], cy[x], u, v)
                    else:
                        cx[x] = u
                        cy[x] = v
                    x = parent[x]

