while(1):
    if(rmax - rmin < 10e-9):
        print((rmin + rmax)/2) 
        break

    r = (rmin + rmax)/2
    p = [math.exp(1 - i/(r**2)) if i > r**2 else 1.0 for i in d]

    dp = [[0] * (n + 1) for i in range(n + 1)]

    dp[0][0] = 1
    for i in range(1, n + 1):
        for j in range(i + 1):
            if(j > 0):
                dp[i][j] = p[i - 1] * dp[i - 1][j - 1]
            if(i != j):
                dp[i][j] += (1 - p[i - 1]) * dp[i - 1][j]

    s = 0
    for j in range(k, n + 1):
        s += dp[n][j]

    if(s > 1 - epsilon):
        rmax = r
    else:
        rmin = r

