    manuel_same = should_same_count - same_count
    buf = []
    if manuel_same <= 0:
        for a, b in zip(s1, s2):
            if a != b:
                if 'a' not in (a, b):
                    buf.append('a')
                elif 'b' not in (a, b):
                    buf.append('b')
                else:
                    buf.append('c')
            else:
                if manuel_same < 0:
                    manuel_same += 1
                    if 'a' == a:
                        buf.append('b')
                    else:
                        buf.append('a')
                else:
                    buf.append(a)
        print ''.join(buf)
    elif manuel_same * 2 <= n - same_count:
        manuel_same *= 2
        for a, b in zip(s1, s2):
            if a != b:
                if manuel_same > 0:
                    if manuel_same & 1 == 1:
                        buf.append(b)
                    else:
                        buf.append(a)
                    manuel_same -= 1
                else:
                    if 'a' not in (a, b):
                        buf.append('a')
                    elif 'b' not in (a, b):
                        buf.append('b')
                    else:
                        buf.append('c')
            else:
                buf.append(a)
        print ''.join(buf)
    else:
        print -1


