def subtract(a1, a2):
    if a1 > a2 + 0.0000001:
        return a1-a2
    elif abs(a1-a2) <= 0.0000001:
        return 0
    return 360+a1-a2

def angle(a1, a2):
    import math
    return math.atan2(a2,a1)*180/math.pi

def start():
    n = input()
    degreesPositive = []
    for _ in xrange(n):
        a1, a2 = map(int, raw_input().split())
        degree = angle(a1, a2)
        if degree < 0:
            degreesPositive.append(degree+360)
        else:
            degreesPositive.append(degree)
    degreesPositive.sort()
    maxValue = abs(subtract(degreesPositive[len(degreesPositive)-1],degreesPositive[len(degreesPositive)-2]))
    for x in xrange(0, len(degreesPositive)-1):
        maxValue = abs(max(maxValue, subtract(degreesPositive[x], degreesPositive[x-1])))
    if maxValue == 0:
        maxValue = 360
    print "%.12f" % (360-maxValue)

start()

