from fractions import gcd
import math

def lcm(x, y):
	return (x * y) // gcd(x, y)

def is_valid(num):
	while num % 3 == 0:
		num /= 3
	while num % 2 == 0:
		num /= 2
	return num == 1

n = int(raw_input())
nums = map(int, raw_input().strip().split(" "))
possible = True

for i in range(1, len(nums)):
	res = lcm(nums[i], nums[i-1])
	m1 = res // nums[i]
	m2 = res // nums[i-1]

	if not is_valid(m1) or not is_valid(m2):
		possible = False
		break

if possible:
	print("Yes")
else:
	print("No")

